INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 1, 'Quel type d''énergie est produit par des panneaux solaires ?', 'L''énergie solaire', ARRAY['L''énergie éolienne', 'L''énergie nucléaire', 'L''énergie hydraulique'], 'fr', true, 'Les panneaux solaires convertissent la lumière du soleil en électricité grâce à des cellules photovoltaïques.'),
('nature', 1, 'Comment appelle-t-on un terrain gorgé d''eau de façon permanente ?', 'Un marécage', ARRAY['Un désert', 'Une prairie', 'Une forêt'], 'fr', true, 'Les marécages sont des zones humides où le sol est saturé d''eau en permanence.'),
('nature', 1, 'Quel champignon comestible pousse souvent au pied des chênes ?', 'Le cèpe', ARRAY['L''amanite tue-mouches', 'Le vénéneux cortinaire', 'La morille'], 'fr', true, 'Le cèpe de Bordeaux est un champignon très apprécié qui pousse près des chênes et des châtaigniers.'),
('nature', 1, 'De quoi sont principalement constitués les récifs coralliens ?', 'De petits animaux marins appelés polypes', ARRAY['De roches volcaniques', 'D''algues géantes', 'De sable compacté'], 'fr', true, 'Les coraux sont des animaux marins (polypes) qui sécrètent un squelette calcaire formant les récifs.'),
('nature', 1, 'Quel est le principal gaz responsable de l''effet de serre ?', 'Le dioxyde de carbone (CO2)', ARRAY['L''oxygène', 'L''azote', 'L''hélium'], 'fr', true, 'Le CO2 piège la chaleur dans l''atmosphère, contribuant au réchauffement climatique.'),
('nature', 1, 'Comment s''appelle la couche supérieure du sol où poussent les plantes ?', 'L''humus', ARRAY['Le magma', 'Le granite', 'Le sable'], 'fr', true, 'L''humus est la couche riche en matière organique décomposée qui nourrit les plantes.'),
('nature', 1, 'Quel animal polaire a une fourrure blanche pour se camoufler ?', 'L''ours polaire', ARRAY['Le pingouin', 'Le phoque', 'Le morse'], 'fr', true, 'L''ours polaire a une fourrure blanche qui lui permet de se fondre dans la neige et la glace.'),
('nature', 1, 'Comment appelle-t-on l''eau souterraine que l''on peut pomper ?', 'Une nappe phréatique', ARRAY['Un glacier', 'Un torrent', 'Un lac artificiel'], 'fr', true, 'Les nappes phréatiques sont des réserves d''eau souterraine alimentées par l''infiltration de la pluie.'),
('nature', 1, 'Quel phénomène météorologique produit des flocons de neige ?', 'Le gel de la vapeur d''eau dans les nuages', ARRAY['Le vent très fort', 'La foudre', 'Les marées'], 'fr', true, 'Les flocons de neige se forment quand la vapeur d''eau cristallise autour de particules dans les nuages froids.'),
('nature', 1, 'Quelle énergie utilise la chaleur de la Terre ?', 'L''énergie géothermique', ARRAY['L''énergie solaire', 'L''énergie éolienne', 'L''énergie marémotrice'], 'fr', true, 'L''énergie géothermique exploite la chaleur naturelle du sous-sol terrestre.'),
('nature', 1, 'Quel est le plus grand animal vivant dans les océans ?', 'La baleine bleue', ARRAY['Le requin blanc', 'Le calmar géant', 'Le cachalot'], 'fr', true, 'La baleine bleue peut mesurer jusqu''à 30 mètres et peser 150 tonnes.'),
('nature', 1, 'Comment appelle-t-on la forêt qui pousse dans l''eau salée des côtes tropicales ?', 'La mangrove', ARRAY['La jungle', 'La garrigue', 'La savane'], 'fr', true, 'La mangrove est un écosystème côtier tropical où des arbres poussent les pieds dans l''eau salée.'),
('nature', 1, 'Quel déchet met le plus de temps à se décomposer dans la nature ?', 'Le verre', ARRAY['Le papier', 'Une peau de banane', 'Un trognon de pomme'], 'fr', true, 'Le verre met environ 4 000 ans à se décomposer dans la nature.'),
('nature', 1, 'Comment les champignons se reproduisent-ils ?', 'Par des spores', ARRAY['Par des graines', 'Par des fleurs', 'Par des œufs'], 'fr', true, 'Les champignons libèrent des spores microscopiques qui germent pour former de nouveaux champignons.'),
('nature', 1, 'Quel continent est recouvert de glace presque entièrement ?', 'L''Antarctique', ARRAY['L''Arctique', 'Le Groenland', 'L''Islande'], 'fr', true, 'L''Antarctique est recouvert à 98 % par une calotte glaciaire.'),
('nature', 1, 'Comment s''appelle le phénomène de montée des eaux de la mer ?', 'La montée du niveau de la mer', ARRAY['Un tsunami', 'Une marée haute', 'Un raz-de-marée'], 'fr', true, 'La montée du niveau de la mer est causée par la fonte des glaciers et la dilatation thermique de l''eau.'),
('nature', 1, 'Quel animal construit des barrages sur les rivières ?', 'Le castor', ARRAY['La loutre', 'Le rat musqué', 'Le ragondin'], 'fr', true, 'Le castor utilise des branches et de la boue pour construire des barrages qui créent des étangs.'),
('nature', 1, 'Quelle plante carnivore attrape les insectes avec ses feuilles collantes ?', 'Le droséra', ARRAY['La tulipe', 'Le tournesol', 'La marguerite'], 'fr', true, 'Le droséra possède des feuilles couvertes de poils gluants qui piègent les insectes.'),
('nature', 1, 'Quel gaz est produit par la décomposition des déchets organiques ?', 'Le méthane', ARRAY['L''oxygène', 'L''hélium', 'Le néon'], 'fr', true, 'Le méthane est un gaz à effet de serre produit par la décomposition de matière organique.'),
('nature', 1, 'Comment appelle-t-on un vent très violent en forme d''entonnoir sur l''eau ?', 'Une trombe marine', ARRAY['Un ouragan', 'Une tempête tropicale', 'Un blizzard'], 'fr', true, 'Une trombe marine est un tourbillon d''air qui se forme au-dessus de l''eau.'),
('nature', 1, 'Quel est le rôle principal des vers de terre dans le sol ?', 'Aérer la terre', ARRAY['Manger les racines', 'Boire l''eau du sol', 'Fabriquer du sable'], 'fr', true, 'Les vers de terre creusent des galeries qui aèrent le sol et facilitent l''infiltration de l''eau.'),
('nature', 1, 'Quelle est la source d''énergie renouvelable la plus utilisée dans le monde ?', 'L''énergie hydraulique', ARRAY['L''énergie solaire', 'L''énergie éolienne', 'L''énergie géothermique'], 'fr', true, 'L''hydroélectricité est la première source d''énergie renouvelable au monde.'),
('nature', 1, 'Quel type de paysage trouve-t-on dans le Sahara ?', 'Des dunes de sable et des rochers', ARRAY['Des forêts tropicales', 'Des marécages', 'Des prairies vertes'], 'fr', true, 'Le Sahara est composé de dunes (ergs), de plateaux rocheux (hamadas) et de plaines caillouteuses (regs).'),
('nature', 1, 'Comment les plantes purifient-elles l''air ?', 'En absorbant le CO2 et rejetant l''oxygène', ARRAY['En absorbant la poussière', 'En chauffant l''air', 'En créant du vent'], 'fr', true, 'Par la photosynthèse, les plantes absorbent le dioxyde de carbone et libèrent de l''oxygène.'),
('nature', 1, 'Quel oiseau marin plonge pour attraper des poissons près des pôles ?', 'Le manchot', ARRAY['Le flamant rose', 'Le pélican', 'La mouette'], 'fr', true, 'Les manchots sont d''excellents nageurs qui plongent pour capturer poissons et krill.'),
('nature', 1, 'Comment appelle-t-on la zone de transition entre la terre et la mer ?', 'Le littoral', ARRAY['L''archipel', 'Le plateau continental', 'La fosse océanique'], 'fr', true, 'Le littoral est la bande de terre qui borde la mer et qui est influencée par les marées.'),
('nature', 1, 'Quel insecte est essentiel à la pollinisation des fleurs ?', 'L''abeille', ARRAY['La mouche', 'Le moustique', 'La fourmi'], 'fr', true, 'Les abeilles transportent le pollen de fleur en fleur, permettant la reproduction des plantes.'),
('nature', 1, 'Comment appelle-t-on une longue période sans pluie ?', 'Une sécheresse', ARRAY['Une mousson', 'Un déluge', 'Une crue'], 'fr', true, 'Une sécheresse est une période prolongée de déficit en précipitations qui assèche les sols.'),
('nature', 1, 'Quel type de sol est le plus fertile pour l''agriculture ?', 'Le terreau', ARRAY['Le sable pur', 'L''argile pure', 'La roche'], 'fr', true, 'Le terreau, riche en humus et nutriments, offre les meilleures conditions pour la croissance des plantes.'),
('nature', 1, 'Quelle partie du champignon voit-on au-dessus du sol ?', 'Le chapeau et le pied', ARRAY['Les racines', 'Les feuilles', 'Les fleurs'], 'fr', true, 'La partie visible est le carpophore (chapeau et pied), tandis que le mycélium reste sous terre.'),
('nature', 1, 'Comment l''eau de mer peut-elle devenir potable ?', 'Par le dessalement', ARRAY['Par le gel', 'En la faisant bouillir seulement', 'En ajoutant du sucre'], 'fr', true, 'Le dessalement retire le sel de l''eau de mer par distillation ou osmose inverse.'),
('nature', 1, 'Quel phénomène provoque la formation des dunes dans le désert ?', 'Le vent', ARRAY['La pluie', 'Les tremblements de terre', 'Les rivières souterraines'], 'fr', true, 'Le vent transporte et accumule les grains de sable pour former des dunes.'),
('nature', 1, 'Quel animal est le symbole de la protection de la nature en France ?', 'Le panda', ARRAY['L''aigle', 'Le loup', 'Le dauphin'], 'fr', true, 'Le panda géant est l''emblème du WWF (World Wildlife Fund), l''une des plus grandes organisations de protection de la nature.'),
('nature', 1, 'Quel est le nom de la couche de glace qui flotte sur la mer en Arctique ?', 'La banquise', ARRAY['Le glacier', 'L''iceberg', 'Le névé'], 'fr', true, 'La banquise est une étendue de glace de mer qui se forme et fond au rythme des saisons.'),
('nature', 1, 'Comment appelle-t-on une pluie mélangée à des polluants industriels ?', 'La pluie acide', ARRAY['La pluie tropicale', 'La bruine', 'L''averse de grêle'], 'fr', true, 'La pluie acide se forme quand les émissions de soufre et d''azote se mélangent à l''eau des nuages.'),
('nature', 1, 'Quelle zone climatique se trouve autour de l''équateur ?', 'La zone tropicale', ARRAY['La zone polaire', 'La zone tempérée', 'La zone aride'], 'fr', true, 'La zone tropicale entoure l''équateur et se caractérise par des températures chaudes toute l''année.'),
('nature', 1, 'Quel est le rôle des racines des palétuviers dans la mangrove ?', 'Stabiliser le sol et protéger la côte', ARRAY['Produire des fruits', 'Attirer les touristes', 'Fabriquer du sel'], 'fr', true, 'Les racines aériennes des palétuviers retiennent les sédiments et protègent le littoral de l''érosion.'),
('nature', 1, 'Quel phénomène naturel lumineux apparaît dans le ciel polaire ?', 'Une aurore boréale', ARRAY['Un arc-en-ciel', 'Une éclipse', 'Un mirage'], 'fr', true, 'Les aurores boréales sont causées par les particules solaires interagissant avec l''atmosphère terrestre.'),
('nature', 1, 'Quelle matière organique enrichit le sol quand les feuilles se décomposent ?', 'Le compost naturel', ARRAY['Le plastique', 'Le pétrole', 'Le charbon'], 'fr', true, 'Les feuilles mortes se décomposent et forment un compost naturel qui enrichit le sol en nutriments.'),
('nature', 1, 'Quel type d''énergie utilise la force de l''eau des rivières ?', 'L''énergie hydraulique', ARRAY['L''énergie éolienne', 'L''énergie solaire', 'L''énergie nucléaire'], 'fr', true, 'L''énergie hydraulique utilise la force du courant ou des chutes d''eau pour produire de l''électricité.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 1, 'Quel poisson remonte les rivières pour pondre ses œufs ?', 'Le saumon', ARRAY['La truite', 'Le brochet', 'La carpe'], 'fr', true, 'Le saumon remonte les rivières depuis la mer pour se reproduire dans les eaux douces où il est né.'),
('nature', 1, 'Comment appelle-t-on une forêt composée principalement de sapins ?', 'Une forêt de conifères', ARRAY['Une forêt tropicale', 'Une mangrove', 'Un maquis'], 'fr', true, 'Les forêts de conifères sont dominées par des arbres à aiguilles comme les sapins, pins et épicéas.'),
('nature', 1, 'Quel phénomène transforme l''eau liquide en vapeur ?', 'L''évaporation', ARRAY['La condensation', 'La congélation', 'La solidification'], 'fr', true, 'L''évaporation est le passage de l''eau de l''état liquide à l''état gazeux sous l''effet de la chaleur.'),
('nature', 1, 'Quel océan borde la côte est de l''Afrique ?', 'L''océan Indien', ARRAY['L''océan Atlantique', 'L''océan Pacifique', 'L''océan Arctique'], 'fr', true, 'L''océan Indien borde les côtes orientales de l''Afrique, du Mozambique à la Somalie.'),
('nature', 1, 'Comment appelle-t-on les oasis dans le désert ?', 'Des points d''eau entourés de végétation', ARRAY['Des lacs salés', 'Des rivières souterraines', 'Des mirages'], 'fr', true, 'Les oasis sont des zones fertiles dans le désert où l''eau souterraine atteint la surface.'),
('nature', 1, 'Quel animal marin possède huit tentacules ?', 'La pieuvre', ARRAY['La méduse', 'L''étoile de mer', 'Le crabe'], 'fr', true, 'La pieuvre (ou poulpe) est un mollusque céphalopode doté de huit tentacules.'),
('nature', 1, 'Comment appelle-t-on le processus de filtration naturelle de l''eau par le sol ?', 'L''infiltration', ARRAY['L''évaporation', 'La condensation', 'La précipitation'], 'fr', true, 'L''infiltration est le processus par lequel l''eau de pluie traverse les couches du sol en se purifiant naturellement.'),
('nature', 1, 'Quel type de zone humide est caractérisé par des tourbières ?', 'Les marais', ARRAY['Les déserts', 'Les prairies', 'Les montagnes'], 'fr', true, 'Les tourbières sont des zones humides où la matière végétale se décompose lentement en formant de la tourbe.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 2, 'Quel processus permet aux champignons de décomposer la matière organique ?', 'La saprophytie', ARRAY['La photosynthèse', 'La fermentation', 'La calcification'], 'fr', true, 'Les champignons saprophytes décomposent la matière organique morte en nutriments réutilisables par les plantes.'),
('nature', 2, 'Quelle zone océanique est la plus profonde ?', 'La zone hadale', ARRAY['La zone abyssale', 'La zone bathypélagique', 'La zone mésopélagique'], 'fr', true, 'La zone hadale correspond aux fosses océaniques de plus de 6 000 m de profondeur.'),
('nature', 2, 'Comment appelle-t-on le réseau souterrain de filaments d''un champignon ?', 'Le mycélium', ARRAY['Le rhizome', 'Le tubercule', 'Le stolon'], 'fr', true, 'Le mycélium est un réseau de filaments (hyphes) qui constitue la partie principale du champignon sous terre.'),
('nature', 2, 'Quel écosystème est le plus riche en biodiversité sur Terre ?', 'La forêt tropicale humide', ARRAY['La toundra', 'Le désert', 'La steppe'], 'fr', true, 'Les forêts tropicales humides abritent plus de 50 % des espèces animales et végétales terrestres.'),
('nature', 2, 'Quel phénomène climatique cyclique réchauffe les eaux du Pacifique ?', 'El Niño', ARRAY['La Niña', 'La mousson', 'Le Gulf Stream'], 'fr', true, 'El Niño est un réchauffement anormal des eaux de surface de l''océan Pacifique tropical qui perturbe le climat mondial.'),
('nature', 2, 'Comment appelle-t-on la relation entre un champignon et les racines d''un arbre ?', 'Une mycorhize', ARRAY['Un parasitisme', 'Une prédation', 'Un commensalisme'], 'fr', true, 'La mycorhize est une symbiose bénéfique où le champignon aide l''arbre à absorber l''eau et les minéraux.'),
('nature', 2, 'Quel type d''énergie renouvelable utilise les marées ?', 'L''énergie marémotrice', ARRAY['L''énergie géothermique', 'L''énergie biomasse', 'L''énergie solaire'], 'fr', true, 'L''énergie marémotrice exploite le mouvement des marées pour produire de l''électricité.'),
('nature', 2, 'Quel animal est considéré comme une espèce clé de voûte dans les récifs coralliens ?', 'L''étoile de mer', ARRAY['Le dauphin', 'La baleine', 'Le requin marteau'], 'fr', true, 'Certaines étoiles de mer contrôlent les populations d''organismes qui pourraient étouffer le corail.'),
('nature', 2, 'Comment appelle-t-on le blanchissement des coraux ?', 'Le blanchissement corallien', ARRAY['L''érosion marine', 'La calcification', 'La salinisation'], 'fr', true, 'Le blanchissement se produit quand les coraux stressés par la chaleur expulsent les algues symbiotiques qui leur donnent leur couleur.'),
('nature', 2, 'Quel gaz volcanique est le plus dangereux pour les populations ?', 'Le dioxyde de soufre', ARRAY['L''oxygène', 'L''azote', 'L''argon'], 'fr', true, 'Le dioxyde de soufre (SO2) est toxique et peut provoquer des pluies acides et des problèmes respiratoires.'),
('nature', 2, 'Quel est le rôle des zones humides pour la qualité de l''eau ?', 'Filtrer et purifier l''eau naturellement', ARRAY['Augmenter la salinité', 'Réchauffer les cours d''eau', 'Acidifier les nappes phréatiques'], 'fr', true, 'Les zones humides agissent comme des filtres naturels en retenant les polluants et sédiments.'),
('nature', 2, 'Comment appelle-t-on un volcan qui n''a pas eu d''éruption depuis très longtemps ?', 'Un volcan dormant', ARRAY['Un volcan éteint', 'Un volcan actif', 'Un volcan sous-marin'], 'fr', true, 'Un volcan dormant n''a pas eu d''éruption récente mais pourrait encore se réveiller.'),
('nature', 2, 'Quel type de désert est caractérisé par des températures très froides ?', 'Le désert froid', ARRAY['Le désert chaud', 'Le désert côtier', 'Le désert subtropical'], 'fr', true, 'Les déserts froids comme le Gobi ou l''Antarctique ont des températures glaciales mais très peu de précipitations.'),
('nature', 2, 'Comment les éoliennes en mer sont-elles appelées ?', 'Des éoliennes offshore', ARRAY['Des éoliennes terrestres', 'Des hydroliennes', 'Des turbines solaires'], 'fr', true, 'Les éoliennes offshore sont installées en mer où les vents sont plus forts et plus constants.'),
('nature', 2, 'Quel phénomène météorologique est mesuré sur l''échelle de Beaufort ?', 'La force du vent', ARRAY['L''intensité de la pluie', 'La température', 'La pression atmosphérique'], 'fr', true, 'L''échelle de Beaufort va de 0 (calme) à 12 (ouragan) et mesure la force du vent.'),
('nature', 2, 'Comment appelle-t-on la zone de l''océan où la lumière ne pénètre plus ?', 'La zone aphotique', ARRAY['La zone épipélagique', 'La zone littorale', 'La zone néritique'], 'fr', true, 'La zone aphotique commence vers 200 m de profondeur, là où la lumière du soleil ne parvient plus.'),
('nature', 2, 'Quel est le premier pays producteur d''énergie éolienne en Europe ?', 'L''Allemagne', ARRAY['La France', 'L''Espagne', 'Le Royaume-Uni'], 'fr', true, 'L''Allemagne est le leader européen de l''énergie éolienne avec la plus grande capacité installée.'),
('nature', 2, 'Quel champignon mortel ressemble à un champignon de Paris ?', 'L''amanite phalloïde', ARRAY['Le bolet bai', 'La girolle', 'Le pied-de-mouton'], 'fr', true, 'L''amanite phalloïde est responsable de 90 % des empoisonnements mortels par champignons en Europe.'),
('nature', 2, 'Comment appelle-t-on la couche du sol la plus profonde, composée de roche mère ?', 'La roche mère', ARRAY['L''humus', 'Le sous-sol', 'La couche arable'], 'fr', true, 'La roche mère est la couche géologique sous-jacente à partir de laquelle le sol s''est formé par altération.'),
('nature', 2, 'Quel phénomène climatique apporte des pluies abondantes en Asie du Sud ?', 'La mousson', ARRAY['El Niño', 'Le mistral', 'L''alizé'], 'fr', true, 'La mousson est un vent saisonnier qui apporte des pluies torrentielles en été en Asie du Sud-Est.'),
('nature', 2, 'Quel mammifère marin vit exclusivement dans l''Arctique ?', 'Le narval', ARRAY['Le dauphin', 'La baleine à bosse', 'Le lamantin'], 'fr', true, 'Le narval est un cétacé arctique reconnaissable à sa longue défense en spirale.'),
('nature', 2, 'Quel type de pollution invisible contamine les océans sous forme de minuscules fragments ?', 'Les microplastiques', ARRAY['Les marées noires', 'Les algues toxiques', 'Le sable radioactif'], 'fr', true, 'Les microplastiques sont des fragments de plastique de moins de 5 mm qui contaminent les écosystèmes marins.'),
('nature', 2, 'Comment appelle-t-on la réintroduction d''espèces dans un milieu naturel ?', 'La réintroduction', ARRAY['L''extinction', 'La domestication', 'La migration'], 'fr', true, 'La réintroduction consiste à relâcher des individus d''une espèce dans un habitat d''où elle avait disparu.'),
('nature', 2, 'Quel phénomène provoque la bioluminescence dans les profondeurs océaniques ?', 'Une réaction chimique dans les organismes', ARRAY['La lumière du soleil filtrée', 'La radioactivité naturelle', 'Les courants chauds'], 'fr', true, 'La bioluminescence est produite par une réaction chimique impliquant la luciférine dans les organismes marins.'),
('nature', 2, 'Quel écosystème côtier protège contre les tsunamis et les tempêtes ?', 'La mangrove', ARRAY['Le désert', 'La toundra', 'La steppe'], 'fr', true, 'Les mangroves absorbent l''énergie des vagues et protègent les côtes contre l''érosion et les catastrophes.'),
('nature', 2, 'Comment appelle-t-on la salinité excessive des sols agricoles ?', 'La salinisation', ARRAY['L''acidification', 'L''érosion', 'La désertification'], 'fr', true, 'La salinisation des sols est causée par une irrigation excessive qui fait remonter les sels à la surface.'),
('nature', 2, 'Quel oiseau est le symbole de la protection des zones humides ?', 'Le flamant rose', ARRAY['L''aigle royal', 'Le moineau', 'Le pigeon'], 'fr', true, 'Le flamant rose dépend des zones humides pour se nourrir et nidifier.'),
('nature', 2, 'Quel processus naturel transforme les roches en sol au fil du temps ?', 'L''altération', ARRAY['La fossilisation', 'La cristallisation', 'La sublimation'], 'fr', true, 'L''altération est la dégradation des roches sous l''effet de l''eau, du gel, du vent et des organismes vivants.'),
('nature', 2, 'Quel pays européen produit le plus d''énergie solaire ?', 'L''Allemagne', ARRAY['L''Espagne', 'La France', 'L''Italie'], 'fr', true, 'L''Allemagne est un leader mondial de l''énergie solaire photovoltaïque malgré un ensoleillement modéré.'),
('nature', 2, 'Comment appelle-t-on un courant marin chaud qui traverse l''Atlantique Nord ?', 'Le Gulf Stream', ARRAY['Le courant de Humboldt', 'Le courant de Benguela', 'Le Kuroshio'], 'fr', true, 'Le Gulf Stream transporte de l''eau chaude du golfe du Mexique vers l''Europe, adoucissant son climat.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 2, 'Quel organisme microscopique produit la majorité de l''oxygène sur Terre ?', 'Le phytoplancton', ARRAY['Les arbres', 'Les algues rouges', 'Les mousses'], 'fr', true, 'Le phytoplancton marin produit entre 50 et 80 % de l''oxygène atmosphérique.'),
('nature', 2, 'Quel type de sol argileux retient trop d''eau et étouffe les racines ?', 'Le sol argileux', ARRAY['Le sol sableux', 'Le sol limoneux', 'Le sol calcaire'], 'fr', true, 'Le sol argileux est très compact et retient l''eau, ce qui peut provoquer l''asphyxie des racines.'),
('nature', 2, 'Quel est le nom de la plus profonde fosse océanique ?', 'La fosse des Mariannes', ARRAY['La fosse de Porto Rico', 'La fosse du Japon', 'La fosse des Tonga'], 'fr', true, 'La fosse des Mariannes atteint 10 994 m de profondeur dans l''océan Pacifique.'),
('nature', 2, 'Comment appelle-t-on l''élévation brusque du niveau de la mer causée par un cyclone ?', 'Une onde de tempête', ARRAY['Un tsunami', 'Une marée d''équinoxe', 'Un mascaret'], 'fr', true, 'L''onde de tempête est une montée soudaine du niveau de la mer causée par les vents et la pression d''un cyclone.'),
('nature', 2, 'Quel champignon forme un anneau de fées dans les prés ?', 'Le marasme des Oréades', ARRAY['Le cèpe de Bordeaux', 'La truffe noire', 'Le bolet Satan'], 'fr', true, 'Le marasme des Oréades pousse en cercle dans les prairies, formant ce qu''on appelle un rond de sorcière.'),
('nature', 2, 'Comment s''appelle la technique de purification de l''eau par UV ?', 'La stérilisation UV', ARRAY['La chloration', 'La distillation', 'La filtration au charbon'], 'fr', true, 'Les rayons ultraviolets détruisent les bactéries et virus présents dans l''eau sans ajouter de produits chimiques.'),
('nature', 2, 'Quel phénomène cause la fonte accélérée du pergélisol arctique ?', 'Le réchauffement climatique', ARRAY['Les marées', 'L''activité volcanique', 'Les courants marins froids'], 'fr', true, 'Le réchauffement climatique fait fondre le pergélisol, libérant du méthane et du CO2 piégés.'),
('nature', 2, 'Quel type de corail construit les atolls dans le Pacifique ?', 'Le corail hermatypique', ARRAY['Le corail mou', 'Le corail noir', 'Le corail rouge'], 'fr', true, 'Les coraux hermatypiques (constructeurs de récifs) contiennent des algues symbiotiques et bâtissent les atolls.'),
('nature', 2, 'Comment appelle-t-on un sol composé majoritairement de matière végétale décomposée ?', 'La tourbe', ARRAY['L''argile', 'Le gravier', 'Le limon'], 'fr', true, 'La tourbe se forme dans les tourbières par accumulation de végétaux en milieu humide et acide.'),
('nature', 2, 'Quel vent chaud et sec souffle dans le sud de la France ?', 'Le sirocco', ARRAY['Le mistral', 'La tramontane', 'Le foehn'], 'fr', true, 'Le sirocco est un vent chaud originaire du Sahara qui peut transporter du sable jusque dans le sud de l''Europe.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 3, 'Quel phénomène océanique crée des cheminées hydrothermales au fond des mers ?', 'L''activité volcanique sous-marine', ARRAY['Les courants de marée', 'La pression atmosphérique', 'L''érosion des fonds marins'], 'fr', true, 'Les cheminées hydrothermales se forment là où le magma réchauffe l''eau de mer qui s''infiltre dans la croûte océanique.'),
('nature', 3, 'Comment appelle-t-on le réseau de champignons qui connecte les arbres d''une forêt ?', 'Le Wood Wide Web', ARRAY['Le réseau racinaire', 'Le système lymphatique', 'La canopée connectée'], 'fr', true, 'Le réseau mycorhizien, surnommé Wood Wide Web, permet aux arbres d''échanger nutriments et signaux chimiques via les champignons.'),
('nature', 3, 'Quel phénomène explique que les déserts côtiers comme l''Atacama reçoivent si peu de pluie ?', 'Les courants marins froids', ARRAY['L''altitude élevée', 'La proximité de l''équateur', 'Les vents chauds'], 'fr', true, 'Le courant froid de Humboldt refroidit l''air côtier, empêchant la formation de nuages de pluie au-dessus de l''Atacama.'),
('nature', 3, 'Quel rôle jouent les lichens dans la colonisation des roches nues ?', 'Ils sont des pionniers qui préparent le sol', ARRAY['Ils protègent les roches de l''érosion', 'Ils réchauffent les roches', 'Ils repoussent les insectes'], 'fr', true, 'Les lichens sécrètent des acides qui dégradent la roche et créent un premier substrat pour d''autres plantes.'),
('nature', 3, 'Qu''est-ce que la thermocline dans l''océan ?', 'Une couche où la température chute brusquement', ARRAY['Une zone de forte salinité', 'Un courant chaud profond', 'Une barrière de corail'], 'fr', true, 'La thermocline est une couche d''eau intermédiaire où la température baisse rapidement avec la profondeur.'),
('nature', 3, 'Quel est le nom du phénomène inverse d''El Niño ?', 'La Niña', ARRAY['El Padre', 'La Madre', 'El Viejo'], 'fr', true, 'La Niña est un refroidissement anormal des eaux du Pacifique, produisant des effets climatiques opposés à El Niño.'),
('nature', 3, 'Comment les tourbières contribuent-elles à la lutte contre le changement climatique ?', 'En stockant d''énormes quantités de carbone', ARRAY['En produisant de l''oxygène', 'En refroidissant l''atmosphère', 'En absorbant la pollution'], 'fr', true, 'Les tourbières stockent environ 30 % du carbone des sols mondiaux alors qu''elles ne couvrent que 3 % des terres.'),
('nature', 3, 'Quel est le nom du phénomène de retournement des eaux d''un lac volcanique libérant du CO2 ?', 'Une éruption limnique', ARRAY['Un geyser', 'Un tsunami lacustre', 'Une avalanche sous-lacustre'], 'fr', true, 'L''éruption limnique du lac Nyos au Cameroun en 1986 a libéré un nuage de CO2 mortel.'),
('nature', 3, 'Quel type d''organisme vit près des cheminées hydrothermales sans lumière solaire ?', 'Des bactéries chimiosynthétiques', ARRAY['Des algues photosynthétiques', 'Des coraux profonds', 'Des méduses fluorescentes'], 'fr', true, 'Ces bactéries utilisent l''énergie chimique des composés minéraux (sulfure d''hydrogène) au lieu de la lumière.'),
('nature', 3, 'Comment appelle-t-on la capacité d''un sol à retenir l''eau ?', 'La capacité de rétention', ARRAY['La porosité', 'La perméabilité', 'La capillarité'], 'fr', true, 'La capacité de rétention dépend de la texture du sol : l''argile retient plus d''eau que le sable.'),
('nature', 3, 'Quel est le processus par lequel les zones humides éliminent les nitrates ?', 'La dénitrification', ARRAY['La nitrification', 'La fixation d''azote', 'La phosphorylation'], 'fr', true, 'La dénitrification est un processus bactérien qui transforme les nitrates en azote gazeux dans les zones humides.'),
('nature', 3, 'Quel phénomène météorologique est une spirale de poussière dans le désert ?', 'Un tourbillon de poussière', ARRAY['Une tempête de sable', 'Un haboob', 'Un simoun'], 'fr', true, 'Les tourbillons de poussière (dust devils) sont de petits vortex localisés causés par le réchauffement du sol.'),
('nature', 3, 'Comment appelle-t-on la symbiose entre une algue et un champignon ?', 'Un lichen', ARRAY['Une mousse', 'Un mycélium', 'Un rhizome'], 'fr', true, 'Le lichen est un organisme composite né de l''association symbiotique entre un champignon et une algue ou cyanobactérie.'),
('nature', 3, 'Quelle est la principale menace pour les récifs coralliens de Nouvelle-Calédonie ?', 'Le réchauffement des eaux', ARRAY['La pêche au filet', 'L''extraction minière sous-marine', 'Les marées noires'], 'fr', true, 'Le réchauffement des eaux provoque le blanchissement et la mort des coraux en Nouvelle-Calédonie.'),
('nature', 3, 'Quel est le nom du cycle biogéochimique qui recycle l''azote dans les sols ?', 'Le cycle de l''azote', ARRAY['Le cycle du carbone', 'Le cycle du phosphore', 'Le cycle du soufre'], 'fr', true, 'Le cycle de l''azote implique la fixation, la nitrification et la dénitrification dans les sols et l''atmosphère.'),
('nature', 3, 'Comment fonctionne l''osmose inverse pour purifier l''eau ?', 'En forçant l''eau à travers une membrane semi-perméable', ARRAY['En chauffant l''eau à ébullition', 'En ajoutant du chlore', 'En exposant l''eau aux UV'], 'fr', true, 'L''osmose inverse utilise la pression pour forcer l''eau à traverser une membrane qui retient les contaminants.'),
('nature', 3, 'Quel phénomène océanique provoque la remontée d''eaux froides riches en nutriments ?', 'L''upwelling', ARRAY['Le downwelling', 'Le thermocline', 'Le courant de dérive'], 'fr', true, 'L''upwelling ramène des eaux profondes riches en nutriments vers la surface, favorisant la productivité biologique.'),
('nature', 3, 'Quel type de champignon peut décomposer le bois en quelques années ?', 'Les champignons lignivores', ARRAY['Les champignons mycorhiziens', 'Les champignons parasites', 'Les champignons endophytes'], 'fr', true, 'Les champignons lignivores possèdent des enzymes capables de dégrader la lignine et la cellulose du bois.'),
('nature', 3, 'Comment appelle-t-on la couche de neige compactée qui se transforme en glace dans un glacier ?', 'Le névé', ARRAY['Le verglas', 'Le givre', 'La congère'], 'fr', true, 'Le névé est de la neige ancienne partiellement compactée qui se transforme progressivement en glace de glacier.'),
('nature', 3, 'Quel écosystème marin abrite la plus grande diversité de poissons ?', 'Les récifs coralliens', ARRAY['La haute mer', 'Les abysses', 'Les mangroves'], 'fr', true, 'Les récifs coralliens, bien qu''ils ne couvrent que 0,1 % des océans, abritent 25 % des espèces marines.'),
('nature', 3, 'Quel phénomène cause les mirages dans le désert ?', 'La réfraction de la lumière par l''air chaud', ARRAY['L''évaporation de l''eau', 'La réflexion sur le sable', 'La poussière en suspension'], 'fr', true, 'Les mirages sont causés par la déviation de la lumière traversant des couches d''air de températures différentes.'),
('nature', 3, 'Comment les herbiers de posidonies contribuent-ils à la santé de la Méditerranée ?', 'Ils produisent de l''oxygène et stabilisent les fonds', ARRAY['Ils réchauffent l''eau', 'Ils augmentent la salinité', 'Ils attirent les requins'], 'fr', true, 'Les herbiers de posidonies sont les poumons de la Méditerranée, oxygénant l''eau et stabilisant les sédiments.'),
('nature', 3, 'Quel est le rôle de l''albédo dans le réchauffement des régions polaires ?', 'Il mesure la réflexion de la lumière par la glace', ARRAY['Il mesure la température de l''air', 'Il contrôle les courants marins', 'Il régule les vents polaires'], 'fr', true, 'L''albédo des surfaces glacées réfléchit le rayonnement solaire. Quand la glace fond, l''albédo diminue et la surface absorbe plus de chaleur.'),
('nature', 3, 'Quel phénomène provoque des tempêtes de sable massives dans le Sahara ?', 'Les vents puissants soulevant les particules fines', ARRAY['L''activité volcanique', 'Les tremblements de terre', 'La fonte des glaciers'], 'fr', true, 'Les tempêtes de sable sahariennes sont provoquées par des vents violents qui peuvent transporter la poussière jusqu''en Europe.'),
('nature', 3, 'Comment les diatomées contribuent-elles à la purification naturelle de l''eau ?', 'En filtrant et absorbant les impuretés', ARRAY['En réchauffant l''eau', 'En augmentant la salinité', 'En repoussant les bactéries'], 'fr', true, 'Les diatomées sont des micro-algues siliceuses qui filtrent l''eau et servent de base aux chaînes alimentaires aquatiques.'),
('nature', 3, 'Quel est le pH typique d''un sol de tourbière ?', 'Acide (pH 3-5)', ARRAY['Neutre (pH 7)', 'Alcalin (pH 8-10)', 'Très alcalin (pH 11-13)'], 'fr', true, 'Les sols de tourbière sont très acides en raison de la décomposition lente de la matière organique et de la présence de sphaignes.'),
('nature', 3, 'Quel gaz piégé dans le pergélisol inquiète les climatologues ?', 'Le méthane', ARRAY['L''ozone', 'L''hélium', 'L''argon'], 'fr', true, 'La fonte du pergélisol libère du méthane, un gaz à effet de serre 80 fois plus puissant que le CO2 sur 20 ans.'),
('nature', 3, 'Comment appelle-t-on l''accumulation de sel à la surface des sols irrigués ?', 'L''efflorescence saline', ARRAY['La lixiviation', 'La laterisation', 'La podzolisation'], 'fr', true, 'L''efflorescence saline apparaît quand l''évaporation fait remonter et cristalliser les sels dissous à la surface du sol.'),
('nature', 3, 'Quel type d''éolienne est conçu pour fonctionner avec des vents faibles ?', 'L''éolienne à axe vertical', ARRAY['L''éolienne offshore', 'L''éolienne tripale classique', 'L''éolienne à concentration'], 'fr', true, 'Les éoliennes à axe vertical captent le vent de toutes directions et peuvent fonctionner avec des vents faibles.'),
('nature', 3, 'Quel rôle jouent les cyanobactéries dans les croûtes biologiques du désert ?', 'Elles fixent l''azote et stabilisent le sol', ARRAY['Elles produisent du sel', 'Elles réchauffent le sable', 'Elles repoussent les insectes'], 'fr', true, 'Les cyanobactéries des croûtes biologiques fixent l''azote atmosphérique et lient les particules de sable entre elles.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 3, 'Quel processus permet aux plantes du désert de réduire leur perte d''eau ?', 'L''ouverture nocturne des stomates (métabolisme CAM)', ARRAY['La photosynthèse accélérée', 'L''absorption par les feuilles', 'La transpiration diurne'], 'fr', true, 'Les plantes CAM (comme les cactus) ouvrent leurs stomates la nuit pour minimiser la perte d''eau par évaporation.'),
('nature', 3, 'Comment s''appelle le phénomène de dépérissement massif des récifs coralliens ?', 'La mortalité corallienne de masse', ARRAY['La marée rouge', 'L''eutrophisation corallienne', 'La fossilisation vivante'], 'fr', true, 'La mortalité de masse des coraux est liée au blanchissement répété causé par des eaux trop chaudes.'),
('nature', 3, 'Quel est le principal avantage des panneaux solaires bifaciaux ?', 'Ils captent la lumière des deux côtés', ARRAY['Ils sont moins chers', 'Ils fonctionnent la nuit', 'Ils n''ont pas besoin de soleil direct'], 'fr', true, 'Les panneaux bifaciaux captent la lumière directe sur la face avant et la lumière réfléchie sur la face arrière.'),
('nature', 3, 'Comment appelle-t-on les prairies sous-marines qui captent le carbone ?', 'Les herbiers marins', ARRAY['Les forêts de kelp', 'Les récifs coralliens', 'Les plateaux continentaux'], 'fr', true, 'Les herbiers marins capturent le carbone 35 fois plus vite que les forêts tropicales à surface égale.'),
('nature', 3, 'Quel organisme forme la base du réseau trophique antarctique ?', 'Le krill', ARRAY['Le phytoplancton uniquement', 'Les poissons', 'Les calmars'], 'fr', true, 'Le krill antarctique (Euphausia superba) est la principale source de nourriture des baleines, phoques et manchots.'),
('nature', 3, 'Quel phénomène explique la couleur rouge du lac Natron en Tanzanie ?', 'Des micro-organismes halophiles', ARRAY['Du sang de flamants', 'De la rouille volcanique', 'Du mercure rouge naturel'], 'fr', true, 'Les archées halophiles et les cyanobactéries produisent des pigments rouges dans les eaux très alcalines du lac Natron.'),
('nature', 3, 'Comment les champignons Armillaria détiennent-ils un record naturel ?', 'C''est le plus grand organisme vivant connu', ARRAY['C''est le plus vieil organisme', 'C''est le plus toxique', 'C''est le plus rapide à croître'], 'fr', true, 'Un Armillaria ostoyae en Oregon couvre 9,6 km² et pourrait avoir plus de 2 400 ans.'),
('nature', 3, 'Quel processus transforme l''eau usée en eau potable dans la nature ?', 'La filtration à travers les sols et les roches', ARRAY['L''évaporation seule', 'La congélation', 'La photosynthèse'], 'fr', true, 'L''eau s''infiltre à travers les couches de sol, sable et roche qui filtrent progressivement les contaminants.'),
('nature', 3, 'Comment les zones humides réduisent-elles le risque d''inondation ?', 'En absorbant et stockant l''excès d''eau comme une éponge', ARRAY['En augmentant le débit des rivières', 'En bloquant la pluie', 'En accélérant l''évaporation'], 'fr', true, 'Les zones humides agissent comme des bassins de rétention naturels qui ralentissent le ruissellement et absorbent les crues.'),
('nature', 3, 'Quel est le nom du phénomène de production de lumière par les dinoflagellés marins ?', 'La bioluminescence', ARRAY['La phosphorescence', 'La fluorescence', 'La chémoluminescence'], 'fr', true, 'Les dinoflagellés émettent de la lumière bleue quand ils sont agités par les vagues, créant des mers brillantes.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 4, 'Quel est le nom du processus par lequel les champignons ectomycorhiziens transfèrent du phosphore aux arbres ?', 'Le transfert via les hyphes extraradicaux', ARRAY['La diffusion passive racinaire', 'L''absorption foliaire directe', 'Le transport par les insectes'], 'fr', true, 'Les hyphes ectomycorhiziens explorent le sol bien au-delà des racines et transportent le phosphore directement aux cellules racinaires.'),
('nature', 4, 'Quel phénomène océanique crée des zones mortes dépourvues d''oxygène ?', 'L''eutrophisation', ARRAY['L''acidification', 'La salinisation', 'La thermocline'], 'fr', true, 'L''eutrophisation est causée par un excès de nutriments (azote, phosphore) qui provoque la prolifération d''algues et l''épuisement de l''oxygène.'),
('nature', 4, 'Comment appelle-t-on les organismes extrêmophiles vivant dans les sources chaudes acides ?', 'Des thermoacidophiles', ARRAY['Des halophiles', 'Des psychrophiles', 'Des barophiles'], 'fr', true, 'Les thermoacidophiles sont des archées qui prospèrent dans des environnements chauds (>60°C) et acides (pH<3).'),
('nature', 4, 'Quel est le mécanisme de la séquestration du carbone bleu par les mangroves ?', 'L''accumulation de matière organique dans les sédiments anoxiques', ARRAY['La photosynthèse rapide des feuilles', 'L''absorption du CO2 par l''eau salée', 'La calcification des racines'], 'fr', true, 'Les mangroves piègent le carbone dans leurs sédiments anoxiques (sans oxygène) où la décomposition est très lente.'),
('nature', 4, 'Quel est le nom du phénomène de migration verticale quotidienne du zooplancton ?', 'La migration nycthémérale', ARRAY['La migration saisonnière', 'Le mouvement pélagique', 'La dérive planctonique'], 'fr', true, 'Le zooplancton remonte en surface la nuit pour se nourrir et descend en profondeur le jour pour éviter les prédateurs.'),
('nature', 4, 'Comment les sols ferrallitiques se forment-ils dans les régions tropicales ?', 'Par altération chimique intense sous climat chaud et humide', ARRAY['Par gel et dégel répétés', 'Par accumulation de sel', 'Par érosion éolienne'], 'fr', true, 'Les sols ferrallitiques résultent d''une altération chimique profonde qui laisse des oxydes de fer et d''aluminium.'),
('nature', 4, 'Quel est le rôle des endophytes fongiques dans les graminées ?', 'Produire des alcaloïdes qui repoussent les herbivores', ARRAY['Colorer les feuilles en vert', 'Accélérer la croissance racinaire', 'Attirer les pollinisateurs'], 'fr', true, 'Les champignons endophytes vivent dans les tissus des graminées et produisent des toxines qui dissuadent les herbivores.'),
('nature', 4, 'Quel processus explique la formation des geysers en Islande ?', 'L''eau souterraine surchauffée par le magma s''expulse sous pression', ARRAY['Les marées provoquent des éruptions d''eau', 'Le vent comprime l''eau souterraine', 'Les glaciers fondent et jaillissent'], 'fr', true, 'L''eau infiltrée est chauffée au-delà de 100°C dans des fissures profondes, puis la pression la projette en surface.'),
('nature', 4, 'Quel est le concept de services écosystémiques rendus par les zones humides ?', 'L''ensemble des bénéfices que les humains tirent des écosystèmes', ARRAY['Le coût d''entretien des parcs naturels', 'La valeur touristique des paysages', 'Le rendement agricole des terres inondables'], 'fr', true, 'Les services écosystémiques incluent la purification de l''eau, la régulation des crues, le stockage du carbone et la biodiversité.'),
('nature', 4, 'Comment les forêts de kelp influencent-elles le cycle du carbone océanique ?', 'En séquestrant le carbone qui coule vers les grands fonds', ARRAY['En rejetant du CO2 dans l''atmosphère', 'En empêchant la photosynthèse du plancton', 'En acidifiant les eaux côtières'], 'fr', true, 'Les kelps géants capturent le CO2 et quand leurs frondes meurent, elles coulent et séquestrent le carbone dans les abysses.'),
('nature', 4, 'Quel est le phénomène de rétroaction positive de l''albédo dans l''Arctique ?', 'La fonte de la glace réduit l''albédo, accélérant le réchauffement', ARRAY['La glace augmente en reflétant plus de chaleur', 'Les nuages refroidissent la surface glacée', 'La neige fraîche absorbe plus de chaleur'], 'fr', true, 'Moins de glace signifie moins de réflexion solaire, plus d''absorption de chaleur par l''océan sombre, et donc plus de fonte.'),
('nature', 4, 'Quel organisme extrêmophile a été découvert dans la fosse des Mariannes ?', 'Des bactéries piézophiles', ARRAY['Des poissons abyssaux géants', 'Des coraux profonds', 'Des algues bioluminescentes'], 'fr', true, 'Les bactéries piézophiles (ou barophiles) prospèrent sous les pressions extrêmes des fosses océaniques profondes.'),
('nature', 4, 'Comment les champignons Trichoderma sont-ils utilisés en agriculture durable ?', 'Comme agents de biocontrôle contre les pathogènes du sol', ARRAY['Comme engrais chimique naturel', 'Comme pesticide à pulvériser', 'Comme nourriture pour les vers de terre'], 'fr', true, 'Les Trichoderma parasitent les champignons pathogènes et stimulent les défenses naturelles des plantes.'),
('nature', 4, 'Quel est le principe de la phytoremédiation des sols pollués ?', 'Utiliser des plantes pour absorber ou dégrader les polluants', ARRAY['Brûler la végétation contaminée', 'Inonder les sols pour diluer les polluants', 'Couvrir le sol de béton'], 'fr', true, 'Certaines plantes hyperaccumulatrices extraient les métaux lourds du sol via leurs racines.'),
('nature', 4, 'Comment fonctionne le système de refroidissement passif des termitières ?', 'Par ventilation naturelle avec des conduits et des cheminées', ARRAY['Par production de glace souterraine', 'Par utilisation de feuilles humides', 'Par réflexion de la lumière'], 'fr', true, 'Les termitières ont un système complexe de tunnels qui créent une circulation d''air naturelle régulant la température.'),
('nature', 4, 'Quel rôle joue le permafrost dans le bilan radiatif terrestre ?', 'Il stocke du carbone organique qui, une fois libéré, amplifie le réchauffement', ARRAY['Il absorbe les rayons UV', 'Il réfléchit les ondes radio', 'Il bloque les rayons cosmiques'], 'fr', true, 'Le pergélisol contient environ 1 500 gigatonnes de carbone organique dont la libération accélérerait le changement climatique.'),
('nature', 4, 'Comment les récifs coralliens mésophotiques diffèrent-ils des récifs de surface ?', 'Ils se trouvent entre 30 et 150 m de profondeur avec moins de lumière', ARRAY['Ils sont plus colorés et diversifiés', 'Ils n''ont pas de polypes', 'Ils sont constitués uniquement de coraux mous'], 'fr', true, 'Les récifs mésophotiques reçoivent peu de lumière et abritent des espèces adaptées à la pénombre, souvent inconnues.'),
('nature', 4, 'Quel phénomène géochimique explique la couleur bleue du lac Pukaki en Nouvelle-Zélande ?', 'La farine de roche glaciaire en suspension', ARRAY['La présence d''algues bleues', 'La réflexion du ciel', 'Un fond de calcaire blanc'], 'fr', true, 'Les particules très fines de roche broyée par les glaciers diffusent la lumière, donnant au lac sa couleur turquoise.'),
('nature', 4, 'Comment les champignons endomycorhiziens pénètrent-ils les cellules racinaires ?', 'En formant des arbuscules à l''intérieur des cellules corticales', ARRAY['En perçant les parois cellulaires avec des enzymes acides', 'En se fixant sur la surface des racines', 'En passant par les stomates des feuilles'], 'fr', true, 'Les champignons endomycorhiziens forment des arbuscules ramifiés dans les cellules racinaires pour échanger nutriments et sucres.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 5, 'Quel est le mécanisme moléculaire par lequel les tardigrades survivent à la dessiccation ?', 'La production de protéines TDP qui remplacent l''eau et vitrifient les cellules', ARRAY['La production de glycérol antigel', 'L''encapsulation dans une coque de chitine', 'La mise en hibernation du métabolisme uniquement'], 'fr', true, 'Les protéines TDP (Tardigrade-specific Disordered Proteins) forment une matrice vitreuse protégeant les structures cellulaires.'),
('nature', 5, 'Comment le champignon Ophiocordyceps unilateralis manipule-t-il le comportement des fourmis ?', 'En sécrétant des métabolites qui altèrent le système nerveux de la fourmi', ARRAY['En bloquant les yeux de la fourmi', 'En émettant des ultrasons', 'En modifiant l''ADN de la fourmi'], 'fr', true, 'Ce champignon parasite modifie le comportement de la fourmi pour qu''elle grimpe en hauteur et morde une feuille, optimisant la dispersion des spores.'),
('nature', 5, 'Quel est le concept de dette d''extinction dans l''écologie de la conservation ?', 'Les extinctions futures déjà programmées par la dégradation passée des habitats', ARRAY['Le nombre d''espèces qui se sont éteintes dans le passé', 'Le coût financier de la protection des espèces', 'Le nombre d''espèces invasives non contrôlées'], 'fr', true, 'La dette d''extinction désigne les espèces qui s''éteindront inévitablement en raison de la fragmentation d''habitats déjà survenue.'),
('nature', 5, 'Comment fonctionne le processus de minéralisation du carbone dans les péridotites d''Oman ?', 'Le CO2 réagit avec les silicates de magnésium pour former des carbonates solides', ARRAY['Le carbone est absorbé par des algues souterraines', 'La chaleur du désert vaporise le CO2', 'Des bactéries transforment le CO2 en méthane'], 'fr', true, 'Les péridotites réagissent naturellement avec le CO2 atmosphérique pour former de la magnésite, séquestrant le carbone de façon permanente.'),
('nature', 5, 'Quel est le rôle des composés organiques volatils biogéniques (COVBs) émis par les forêts ?', 'Ils forment des aérosols qui nucléent les nuages et influencent le climat', ARRAY['Ils repoussent tous les insectes', 'Ils détruisent la couche d''ozone', 'Ils acidifient les sols forestiers'], 'fr', true, 'Les COVBs comme l''isoprène et les terpènes s''oxydent en aérosols organiques secondaires qui servent de noyaux de condensation pour les nuages.'),
('nature', 5, 'Comment les poissons des zones hadales résistent-ils aux pressions de plus de 1 000 atmosphères ?', 'Grâce à l''oxyde de triméthylamine (TMAO) qui stabilise les protéines', ARRAY['Par des os renforcés en calcium', 'Par une peau blindée de cartilage', 'Par un métabolisme anaérobie total'], 'fr', true, 'Le TMAO contrecarre l''effet de la pression qui déforme les protéines, permettant aux enzymes de fonctionner normalement.'),
('nature', 5, 'Quel est le concept de la pompe biologique de carbone dans l''océan ?', 'Le transfert du carbone fixé par le phytoplancton vers les profondeurs via la sédimentation', ARRAY['Le relargage de CO2 par les volcans sous-marins', 'La dissolution du calcaire dans l''eau de mer', 'La photosynthèse des algues des grands fonds'], 'fr', true, 'Le phytoplancton fixe le CO2 en surface, puis les pelotes fécales et débris organiques coulent, exportant le carbone en profondeur.'),
('nature', 5, 'Comment le réseau mycorhizien permet-il la reconnaissance du parentage chez les arbres ?', 'Les arbres mères transfèrent plus de carbone aux semis de leur propre espèce via le réseau fongique', ARRAY['Les arbres communiquent par ultrasons racinaires', 'Les feuilles tombées nourrissent sélectivement les descendants', 'Les racines fusionnent génétiquement'], 'fr', true, 'Les recherches de Suzanne Simard ont montré que les arbres mères favorisent leurs propres semis en transférant du carbone et des signaux de défense via les mycorhizes.'),
('nature', 5, 'Quel est le phénomène de clathrate gun hypothesis concernant le méthane océanique ?', 'Le réchauffement pourrait déstabiliser les hydrates de méthane du fond marin, libérant massivement du CH4', ARRAY['Les volcans sous-marins émettent du méthane en continu', 'Les bactéries méthanogènes se multiplient en surface', 'Les icebergs contiennent des poches de méthane'], 'fr', true, 'Les clathrates de méthane sont des structures de glace piégeant du CH4, qui pourraient se déstabiliser si les fonds marins se réchauffent.'),
('nature', 5, 'Comment les cyanobactéries du genre Nostoc fixent-elles l''azote atmosphérique ?', 'Via des hétérocystes qui maintiennent un environnement anaérobie pour la nitrogénase', ARRAY['Par photosynthèse modifiée dans toutes les cellules', 'En absorbant les nitrates du sol', 'En capturant l''azote par des pili extracellulaires'], 'fr', true, 'Les hétérocystes sont des cellules spécialisées aux parois épaisses qui protègent l''enzyme nitrogénase, sensible à l''oxygène.'),
('nature', 5, 'Quel est le mécanisme de la weathering enhancement par les champignons mycorhiziens ?', 'Les hyphes sécrètent des acides organiques qui dissolvent les minéraux de la roche', ARRAY['Les champignons chauffent les roches par fermentation', 'Les spores s''infiltrent dans les fissures et éclatent la roche', 'Les mycéliums absorbent l''humidité et gèlent la roche'], 'fr', true, 'Les acides organiques et les enzymes fongiques dissolvent les minéraux des roches, libérant phosphore et potassium pour les plantes.'),
('nature', 5, 'Comment les récifs coralliens profonds (cold-water corals) se nourrissent-ils sans photosynthèse ?', 'Par capture de particules organiques en suspension dans le courant', ARRAY['Par symbiose avec des bactéries sulfureuses', 'Par absorption directe de nutriments dissous', 'Par prédation active de petits poissons'], 'fr', true, 'Les coraux d''eau froide sont des filtreurs qui capturent le zooplancton et la matière organique transportés par les courants.'),
('nature', 5, 'Quel est le concept de tipping point appliqué à la forêt amazonienne ?', 'Un seuil de déforestation au-delà duquel la forêt se transforme irréversiblement en savane', ARRAY['Le moment où la forêt atteint sa taille maximale', 'La saison où les arbres perdent leurs feuilles', 'Le point de saturation en CO2 des arbres'], 'fr', true, 'Les scientifiques estiment qu''entre 20 et 25 % de déforestation pourrait déclencher un assèchement irréversible de l''Amazonie.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 1, 'What type of energy do wind turbines produce?', 'Wind energy', ARRAY['Solar energy', 'Nuclear energy', 'Geothermal energy'], 'en', true, 'Wind turbines convert the kinetic energy of wind into electrical energy.'),
('nature', 1, 'What is a wetland?', 'An area of land that is saturated with water', ARRAY['A dry desert', 'A mountain peak', 'A deep cave'], 'en', true, 'Wetlands are areas where water covers the soil or is near the surface year-round or seasonally.'),
('nature', 1, 'What do mushrooms grow from underground?', 'Mycelium', ARRAY['Roots', 'Seeds', 'Bulbs'], 'en', true, 'Mycelium is a network of fungal threads underground from which mushrooms sprout.'),
('nature', 1, 'What are coral reefs mainly made of?', 'Tiny marine animals called polyps', ARRAY['Volcanic rocks', 'Compressed sand', 'Giant seaweed'], 'en', true, 'Coral polyps secrete calcium carbonate to build the hard structures that form reefs.'),
('nature', 1, 'What is the main greenhouse gas released by burning fossil fuels?', 'Carbon dioxide (CO2)', ARRAY['Oxygen', 'Nitrogen', 'Helium'], 'en', true, 'Burning coal, oil, and gas releases CO2, the primary driver of climate change.'),
('nature', 1, 'What is the top layer of soil called?', 'Topsoil', ARRAY['Bedrock', 'Clay', 'Gravel'], 'en', true, 'Topsoil is the uppermost layer of soil, rich in organic matter and nutrients for plant growth.'),
('nature', 1, 'Which polar animal has thick white fur for camouflage?', 'The polar bear', ARRAY['The penguin', 'The walrus', 'The seal'], 'en', true, 'Polar bears have white fur that helps them blend in with the Arctic snow and ice.'),
('nature', 1, 'What is an underground water reserve called?', 'An aquifer', ARRAY['A glacier', 'A reservoir', 'A waterfall'], 'en', true, 'Aquifers are underground layers of rock or sediment that hold groundwater.'),
('nature', 1, 'How are snowflakes formed?', 'Water vapor freezes into ice crystals in clouds', ARRAY['Rain freezes as it falls', 'Wind blows ice from glaciers', 'Clouds burst and release ice'], 'en', true, 'Snowflakes form when water vapor crystallizes around tiny particles in cold clouds.'),
('nature', 1, 'What renewable energy source uses heat from inside the Earth?', 'Geothermal energy', ARRAY['Solar energy', 'Wind energy', 'Tidal energy'], 'en', true, 'Geothermal energy taps into the natural heat beneath the Earth''s surface.'),
('nature', 1, 'What is the largest animal on Earth?', 'The blue whale', ARRAY['The great white shark', 'The giant squid', 'The elephant'], 'en', true, 'Blue whales can reach up to 30 meters in length and weigh 150 tonnes.'),
('nature', 1, 'What type of forest grows in tropical coastal saltwater?', 'Mangrove', ARRAY['Rainforest', 'Taiga', 'Savanna'], 'en', true, 'Mangroves are tropical coastal ecosystems where salt-tolerant trees grow in tidal waters.'),
('nature', 1, 'Which type of waste takes the longest to decompose?', 'Glass', ARRAY['Paper', 'A banana peel', 'A cotton shirt'], 'en', true, 'Glass can take up to 4,000 years to decompose in the environment.'),
('nature', 1, 'How do mushrooms reproduce?', 'By releasing spores', ARRAY['By producing seeds', 'By growing flowers', 'By laying eggs'], 'en', true, 'Fungi release microscopic spores that germinate to form new fungal organisms.'),
('nature', 1, 'Which continent is almost entirely covered by ice?', 'Antarctica', ARRAY['The Arctic', 'Greenland', 'Iceland'], 'en', true, 'Antarctica is covered by an ice sheet that contains 98% of its land surface.'),
('nature', 1, 'What causes sea levels to rise?', 'Melting glaciers and thermal expansion of water', ARRAY['Underwater volcanoes', 'Increased rainfall', 'More rivers flowing into the ocean'], 'en', true, 'Rising temperatures melt ice sheets and cause ocean water to expand, raising sea levels.'),
('nature', 1, 'Which animal builds dams on rivers?', 'The beaver', ARRAY['The otter', 'The muskrat', 'The platypus'], 'en', true, 'Beavers use branches, mud, and stones to build dams that create ponds.'),
('nature', 1, 'Which carnivorous plant catches insects with sticky leaves?', 'The sundew', ARRAY['The tulip', 'The sunflower', 'The daisy'], 'en', true, 'Sundews have leaves covered in sticky tentacles that trap and digest insects.'),
('nature', 1, 'What gas is produced by decomposing organic waste?', 'Methane', ARRAY['Oxygen', 'Helium', 'Neon'], 'en', true, 'Methane is a greenhouse gas produced when organic matter decomposes without oxygen.'),
('nature', 1, 'What is a water spout?', 'A tornado that forms over water', ARRAY['A strong ocean wave', 'A tropical storm', 'A tidal wave'], 'en', true, 'A waterspout is a rotating column of air over a body of water, similar to a tornado.'),
('nature', 1, 'What is the main role of earthworms in soil?', 'To aerate the soil', ARRAY['To eat plant roots', 'To drink groundwater', 'To make sand'], 'en', true, 'Earthworms dig tunnels that aerate soil and help water infiltrate the ground.'),
('nature', 1, 'What is the most used renewable energy source worldwide?', 'Hydroelectric power', ARRAY['Solar energy', 'Wind energy', 'Geothermal energy'], 'en', true, 'Hydroelectricity is the world''s largest source of renewable energy.'),
('nature', 1, 'What does the Sahara Desert mainly look like?', 'Sand dunes and rocky plateaus', ARRAY['Tropical forests', 'Swamps', 'Green meadows'], 'en', true, 'The Sahara has sand dunes (ergs), rocky plateaus (hamadas), and stony plains (regs).'),
('nature', 1, 'How do plants purify the air?', 'By absorbing CO2 and releasing oxygen', ARRAY['By absorbing dust', 'By heating the air', 'By creating wind'], 'en', true, 'Through photosynthesis, plants absorb carbon dioxide and release oxygen.'),
('nature', 1, 'What is the name of the ice layer floating on the Arctic Ocean?', 'Sea ice (pack ice)', ARRAY['A glacier', 'An iceberg', 'A snow drift'], 'en', true, 'Sea ice forms when ocean water freezes and can grow or shrink with the seasons.'),
('nature', 1, 'What is rain mixed with industrial pollutants called?', 'Acid rain', ARRAY['Tropical rain', 'Drizzle', 'Hailstorm'], 'en', true, 'Acid rain forms when sulfur dioxide and nitrogen oxide emissions mix with atmospheric water.'),
('nature', 1, 'What climate zone surrounds the equator?', 'The tropical zone', ARRAY['The polar zone', 'The temperate zone', 'The arid zone'], 'en', true, 'The tropical zone straddles the equator and features warm temperatures year-round.'),
('nature', 1, 'What natural light phenomenon appears in polar skies?', 'The aurora borealis (northern lights)', ARRAY['A rainbow', 'An eclipse', 'A mirage'], 'en', true, 'Auroras are caused by solar particles interacting with Earth''s magnetic field and atmosphere.'),
('nature', 1, 'What enriches the soil when dead leaves decompose?', 'Natural compost', ARRAY['Plastic', 'Oil', 'Coal'], 'en', true, 'Decomposing leaves form humus, a natural compost that enriches the soil with nutrients.'),
('nature', 1, 'What type of energy uses the force of flowing water?', 'Hydroelectric energy', ARRAY['Wind energy', 'Solar energy', 'Nuclear energy'], 'en', true, 'Hydroelectric energy harnesses the force of rivers and waterfalls to generate electricity.'),
('nature', 1, 'Which fish swims upstream to lay its eggs?', 'The salmon', ARRAY['The trout', 'The pike', 'The carp'], 'en', true, 'Salmon migrate from the ocean up rivers to spawn in the freshwater streams where they were born.'),
('nature', 1, 'What is a forest made mainly of pine and spruce trees called?', 'A coniferous forest', ARRAY['A tropical forest', 'A mangrove', 'A scrubland'], 'en', true, 'Coniferous forests are dominated by needle-leaved evergreen trees like pine, spruce, and fir.'),
('nature', 1, 'What process turns liquid water into vapor?', 'Evaporation', ARRAY['Condensation', 'Freezing', 'Solidification'], 'en', true, 'Evaporation is the process where liquid water turns into water vapor due to heat.'),
('nature', 1, 'What are oases in the desert?', 'Fertile spots where underground water reaches the surface', ARRAY['Salt lakes', 'Underground rivers', 'Mirages'], 'en', true, 'Oases form where groundwater rises to the surface, allowing plants to grow in the desert.'),
('nature', 1, 'Which marine animal has eight tentacles?', 'The octopus', ARRAY['The jellyfish', 'The starfish', 'The crab'], 'en', true, 'The octopus is a cephalopod mollusc with eight flexible tentacles.'),
('nature', 1, 'What is the natural process of water filtering through soil called?', 'Infiltration', ARRAY['Evaporation', 'Condensation', 'Precipitation'], 'en', true, 'Infiltration is how rainwater seeps through soil layers, naturally purifying as it goes.'),
('nature', 1, 'What is a prolonged period without rain called?', 'A drought', ARRAY['A monsoon', 'A flood', 'A blizzard'], 'en', true, 'A drought is an extended period of below-normal rainfall that dries out the land.'),
('nature', 1, 'Which insect is most important for pollinating flowers?', 'The bee', ARRAY['The fly', 'The mosquito', 'The ant'], 'en', true, 'Bees carry pollen from flower to flower, enabling plant reproduction.'),
('nature', 1, 'What part of a mushroom is visible above ground?', 'The cap and stem', ARRAY['The roots', 'The leaves', 'The flowers'], 'en', true, 'The visible part is the fruiting body (cap and stem), while mycelium remains underground.'),
('nature', 1, 'How can seawater be made drinkable?', 'Through desalination', ARRAY['By freezing it', 'By boiling it only', 'By adding sugar'], 'en', true, 'Desalination removes salt from seawater through distillation or reverse osmosis.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 1, 'What causes sand dunes to form in deserts?', 'Wind', ARRAY['Rain', 'Earthquakes', 'Underground rivers'], 'en', true, 'Wind carries and deposits sand grains, building them into dunes over time.'),
('nature', 1, 'What is the transition zone between land and sea called?', 'The coastline (littoral)', ARRAY['An archipelago', 'A continental shelf', 'An ocean trench'], 'en', true, 'The coastline is the strip of land along the sea influenced by tides and waves.'),
('nature', 1, 'Which type of wetland is characterized by peat bogs?', 'Marshes', ARRAY['Deserts', 'Prairies', 'Mountains'], 'en', true, 'Peat bogs are wetlands where plant material decomposes slowly to form peat.'),
('nature', 1, 'What type of soil is best for farming?', 'Loam (rich topsoil)', ARRAY['Pure sand', 'Pure clay', 'Solid rock'], 'en', true, 'Loam is a mix of sand, silt, clay, and organic matter that provides ideal growing conditions.'),
('nature', 1, 'What phenomenon causes wind to form?', 'Differences in air pressure', ARRAY['Ocean waves', 'Earthquakes', 'Moonlight'], 'en', true, 'Wind forms when air moves from areas of high pressure to areas of low pressure.'),
('nature', 1, 'Which seabird dives to catch fish near the poles?', 'The penguin', ARRAY['The flamingo', 'The pelican', 'The seagull'], 'en', true, 'Penguins are excellent swimmers that dive to catch fish and krill in polar waters.'),
('nature', 1, 'What role do mangrove roots play along tropical coasts?', 'They stabilize the soil and protect the coast', ARRAY['They produce fruit', 'They attract tourists', 'They make salt'], 'en', true, 'Mangrove roots trap sediment and shield coastlines from erosion, waves, and storms.'),
('nature', 1, 'What is compost?', 'Decomposed organic matter used to enrich soil', ARRAY['A type of fertilizer made from chemicals', 'Crushed rocks mixed with water', 'Dry leaves stored in bags'], 'en', true, 'Compost is created by the natural decomposition of food scraps, leaves, and other organic materials.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 2, 'What is the underground network of fungal threads called?', 'Mycelium', ARRAY['Rhizome', 'Tuber', 'Stolon'], 'en', true, 'Mycelium is the vegetative part of a fungus, consisting of a web of hyphes that grows underground.'),
('nature', 2, 'Which ocean zone is the deepest?', 'The hadal zone', ARRAY['The abyssal zone', 'The bathypelagic zone', 'The mesopelagic zone'], 'en', true, 'The hadal zone refers to ocean trenches deeper than 6,000 meters.'),
('nature', 2, 'What is the symbiotic relationship between fungi and tree roots called?', 'Mycorrhiza', ARRAY['Parasitism', 'Predation', 'Commensalism'], 'en', true, 'Mycorrhizal fungi help trees absorb water and minerals in exchange for sugars from photosynthesis.'),
('nature', 2, 'Which ecosystem has the highest biodiversity on Earth?', 'Tropical rainforests', ARRAY['Tundra', 'Deserts', 'Grasslands'], 'en', true, 'Tropical rainforests contain over 50% of the world''s plant and animal species.'),
('nature', 2, 'What cyclical climate phenomenon warms Pacific Ocean waters?', 'El Nino', ARRAY['La Nina', 'The Gulf Stream', 'The monsoon'], 'en', true, 'El Nino is an abnormal warming of surface waters in the tropical Pacific that disrupts global weather patterns.'),
('nature', 2, 'What renewable energy source uses ocean tides?', 'Tidal energy', ARRAY['Geothermal energy', 'Biomass energy', 'Solar energy'], 'en', true, 'Tidal energy harnesses the predictable movement of tides to generate electricity.'),
('nature', 2, 'What happens during coral bleaching?', 'Corals expel their symbiotic algae due to heat stress', ARRAY['Corals are painted white by humans', 'Sand covers the coral', 'Fish eat the coral color'], 'en', true, 'When water is too warm, corals eject the colorful algae living in them, turning white and becoming vulnerable.'),
('nature', 2, 'What is the Beaufort scale used to measure?', 'Wind force', ARRAY['Rainfall intensity', 'Temperature', 'Atmospheric pressure'], 'en', true, 'The Beaufort scale ranges from 0 (calm) to 12 (hurricane force) and measures wind speed.'),
('nature', 2, 'What is the ocean zone where sunlight cannot reach called?', 'The aphotic zone', ARRAY['The epipelagic zone', 'The littoral zone', 'The neritic zone'], 'en', true, 'The aphotic zone begins around 200 meters depth where sunlight no longer penetrates.'),
('nature', 2, 'Which deadly mushroom looks like a common edible species?', 'The death cap (Amanita phalloides)', ARRAY['The chanterelle', 'The porcini', 'The hedgehog mushroom'], 'en', true, 'The death cap causes over 90% of fatal mushroom poisonings worldwide.'),
('nature', 2, 'What is the rock layer at the very bottom of soil called?', 'Bedrock', ARRAY['Topsoil', 'Subsoil', 'Humus'], 'en', true, 'Bedrock is the solid rock underlying the soil, from which the upper layers gradually form.'),
('nature', 2, 'What seasonal wind brings heavy rains to South Asia?', 'The monsoon', ARRAY['El Nino', 'The mistral', 'The trade winds'], 'en', true, 'The monsoon is a seasonal wind pattern that brings heavy rainfall to South and Southeast Asia in summer.'),
('nature', 2, 'Which Arctic marine mammal has a spiral tusk?', 'The narwhal', ARRAY['The dolphin', 'The humpback whale', 'The manatee'], 'en', true, 'The narwhal is an Arctic cetacean with a distinctive long spiral tusk, actually an elongated tooth.'),
('nature', 2, 'What type of invisible pollution contaminates oceans in tiny fragments?', 'Microplastics', ARRAY['Oil spills', 'Toxic algae', 'Radioactive sand'], 'en', true, 'Microplastics are plastic fragments smaller than 5mm found throughout marine ecosystems.'),
('nature', 2, 'What is the reintroduction of species into their natural habitat called?', 'Wildlife reintroduction', ARRAY['Extinction', 'Domestication', 'Migration'], 'en', true, 'Reintroduction involves releasing captive-bred or translocated animals into habitats where they had disappeared.'),
('nature', 2, 'What causes bioluminescence in deep-sea creatures?', 'A chemical reaction involving luciferin', ARRAY['Filtered sunlight', 'Natural radioactivity', 'Warm currents'], 'en', true, 'Bioluminescence is produced by a chemical reaction between luciferin and luciferase enzymes.'),
('nature', 2, 'Which coastal ecosystem protects against tsunamis?', 'Mangroves', ARRAY['Deserts', 'Tundra', 'Grasslands'], 'en', true, 'Mangroves absorb wave energy and protect shorelines from erosion and storm damage.'),
('nature', 2, 'What is excessive salt buildup in agricultural soils called?', 'Salinization', ARRAY['Acidification', 'Erosion', 'Desertification'], 'en', true, 'Salinization occurs when over-irrigation causes salts to rise to the soil surface.'),
('nature', 2, 'What natural process breaks down rocks into soil over time?', 'Weathering', ARRAY['Fossilization', 'Crystallization', 'Sublimation'], 'en', true, 'Weathering is the breakdown of rocks by water, ice, wind, and biological activity over time.'),
('nature', 2, 'What warm ocean current flows across the North Atlantic?', 'The Gulf Stream', ARRAY['The Humboldt Current', 'The Benguela Current', 'The Kuroshio Current'], 'en', true, 'The Gulf Stream carries warm water from the Gulf of Mexico toward Europe, moderating its climate.'),
('nature', 2, 'What microscopic organism produces most of Earth''s oxygen?', 'Phytoplankton', ARRAY['Trees', 'Red algae', 'Mosses'], 'en', true, 'Marine phytoplankton produce between 50% and 80% of the oxygen in Earth''s atmosphere.'),
('nature', 2, 'What is the deepest ocean trench in the world?', 'The Mariana Trench', ARRAY['The Puerto Rico Trench', 'The Japan Trench', 'The Tonga Trench'], 'en', true, 'The Mariana Trench in the Pacific Ocean reaches 10,994 meters at Challenger Deep.'),
('nature', 2, 'What type of energy comes from burning wood, crops, or organic waste?', 'Biomass energy', ARRAY['Nuclear energy', 'Geothermal energy', 'Tidal energy'], 'en', true, 'Biomass energy comes from organic materials like wood, crop residues, and animal waste.'),
('nature', 2, 'What is the sudden rise in sea level caused by a hurricane called?', 'A storm surge', ARRAY['A tsunami', 'A tidal bore', 'A spring tide'], 'en', true, 'A storm surge is a rapid rise in sea level driven by a hurricane''s winds and low pressure.'),
('nature', 2, 'What fairy-ring mushroom grows in circles in meadows?', 'The fairy ring champignon (Marasmius oreades)', ARRAY['The porcini', 'The black truffle', 'The Satan''s bolete'], 'en', true, 'Marasmius oreades grows outward in expanding circles, creating the classic fairy ring pattern in grass.'),
('nature', 2, 'How does UV water purification work?', 'UV rays destroy bacteria and viruses without chemicals', ARRAY['UV light heats water to boiling', 'UV rays remove salt', 'UV light changes the pH'], 'en', true, 'Ultraviolet light damages the DNA of microorganisms, rendering them unable to reproduce.'),
('nature', 2, 'What is causing accelerated melting of Arctic permafrost?', 'Climate change', ARRAY['Ocean tides', 'Volcanic activity', 'Cold ocean currents'], 'en', true, 'Rising global temperatures are thawing permafrost, releasing trapped methane and CO2.'),
('nature', 2, 'What type of coral builds atolls in the Pacific?', 'Hermatypic (reef-building) coral', ARRAY['Soft coral', 'Black coral', 'Red coral'], 'en', true, 'Hermatypic corals contain symbiotic algae and build the calcium carbonate structures that form atolls.'),
('nature', 2, 'What is soil composed mainly of decomposed plant material called?', 'Peat', ARRAY['Clay', 'Gravel', 'Silt'], 'en', true, 'Peat forms in waterlogged, acidic conditions where plant material decomposes very slowly.'),
('nature', 2, 'What hot dry wind blows from the Sahara into Southern Europe?', 'The sirocco', ARRAY['The mistral', 'The tramontane', 'The foehn'], 'en', true, 'The sirocco carries hot, dry air and sometimes Saharan dust across the Mediterranean into Europe.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 2, 'What is the role of wetlands in water quality?', 'They filter and purify water naturally', ARRAY['They increase salinity', 'They warm waterways', 'They acidify groundwater'], 'en', true, 'Wetlands act as natural filters, trapping pollutants and sediments from the water that flows through them.'),
('nature', 2, 'What climate phenomenon is the opposite of El Nino?', 'La Nina', ARRAY['The Gulf Stream', 'The monsoon', 'The trade winds'], 'en', true, 'La Nina involves abnormal cooling of Pacific waters, causing opposite weather effects to El Nino.'),
('nature', 2, 'Which leading European country generates the most solar energy?', 'Germany', ARRAY['Spain', 'France', 'Italy'], 'en', true, 'Germany is a world leader in solar photovoltaic energy despite its moderate sunshine levels.'),
('nature', 2, 'What are offshore wind turbines?', 'Wind turbines installed at sea where winds are stronger', ARRAY['Onshore turbines near the coast', 'Underwater turbines', 'Solar-powered water turbines'], 'en', true, 'Offshore wind farms are built in the ocean where stronger, more consistent winds generate more electricity.'),
('nature', 2, 'What is a dormant volcano?', 'A volcano that has not erupted recently but could become active again', ARRAY['An extinct volcano', 'An active volcano', 'A submarine volcano'], 'en', true, 'Dormant volcanoes have not erupted in recent history but are not considered permanently extinct.'),
('nature', 2, 'What type of desert has freezing temperatures?', 'A cold desert', ARRAY['A hot desert', 'A coastal desert', 'A subtropical desert'], 'en', true, 'Cold deserts like the Gobi and Antarctica have frigid temperatures but very little precipitation.'),
('nature', 2, 'What bird is a symbol of wetland conservation?', 'The flamingo', ARRAY['The golden eagle', 'The sparrow', 'The pigeon'], 'en', true, 'Flamingos depend on wetlands for feeding and nesting, making them icons of wetland ecosystems.'),
('nature', 2, 'What type of clay soil holds too much water and suffocates roots?', 'Clay soil', ARRAY['Sandy soil', 'Loamy soil', 'Chalky soil'], 'en', true, 'Clay soil is very compact and retains excess water, which can cause root asphyxiation in plants.'),
('nature', 2, 'What type of energy comes from the movement of ocean waves?', 'Wave energy', ARRAY['Tidal energy', 'Geothermal energy', 'Biomass energy'], 'en', true, 'Wave energy converters capture the kinetic energy of ocean waves to generate electricity.'),
('nature', 2, 'What is the process of reintroducing wolves to an ecosystem called when it creates a cascade of positive effects?', 'A trophic cascade', ARRAY['A food web collapse', 'An ecological disaster', 'A monoculture effect'], 'en', true, 'Trophic cascades occur when top predators like wolves regulate prey populations, benefiting vegetation and entire ecosystems.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 3, 'What creates hydrothermal vents on the ocean floor?', 'Underwater volcanic activity', ARRAY['Tidal currents', 'Atmospheric pressure', 'Seafloor erosion'], 'en', true, 'Hydrothermal vents form where magma heats seawater that seeps through cracks in the oceanic crust.'),
('nature', 3, 'What is the fungal network connecting trees in a forest nicknamed?', 'The Wood Wide Web', ARRAY['The root network', 'The forest highway', 'The canopy connection'], 'en', true, 'Mycorrhizal networks allow trees to share nutrients and chemical signals through underground fungi.'),
('nature', 3, 'Why does the Atacama coastal desert receive almost no rain?', 'Cold ocean currents prevent cloud formation', ARRAY['High altitude', 'Proximity to the equator', 'Hot winds from the interior'], 'en', true, 'The cold Humboldt Current cools coastal air, suppressing the formation of rain clouds over the Atacama.'),
('nature', 3, 'What role do lichens play on bare rock surfaces?', 'They are pioneer organisms that create initial soil', ARRAY['They protect rocks from erosion', 'They warm the rocks', 'They repel insects'], 'en', true, 'Lichens secrete acids that slowly break down rock, creating a thin substrate for other plants to colonize.'),
('nature', 3, 'What is the thermocline in the ocean?', 'A layer where temperature drops sharply with depth', ARRAY['A zone of high salinity', 'A deep warm current', 'A coral barrier'], 'en', true, 'The thermocline is an intermediate water layer where temperature decreases rapidly with increasing depth.'),
('nature', 3, 'What is the opposite climate phenomenon to El Nino?', 'La Nina', ARRAY['El Padre', 'La Madre', 'El Viejo'], 'en', true, 'La Nina involves abnormal cooling of Pacific waters, producing opposite weather effects to El Nino.'),
('nature', 3, 'How do peatlands help fight climate change?', 'By storing enormous amounts of carbon', ARRAY['By producing oxygen', 'By cooling the atmosphere', 'By absorbing pollution'], 'en', true, 'Peatlands store about 30% of global soil carbon despite covering only 3% of the Earth''s land surface.'),
('nature', 3, 'What is a limnic eruption?', 'A sudden release of CO2 from a volcanic lake', ARRAY['A geyser', 'A lake tsunami', 'An underwater landslide'], 'en', true, 'The 1986 limnic eruption at Lake Nyos in Cameroon released a deadly cloud of CO2.'),
('nature', 3, 'What organisms thrive near hydrothermal vents without sunlight?', 'Chemosynthetic bacteria', ARRAY['Photosynthetic algae', 'Deep corals', 'Fluorescent jellyfish'], 'en', true, 'These bacteria use chemical energy from hydrogen sulfide instead of sunlight to produce food.'),
('nature', 3, 'What is the process by which wetlands remove nitrates from water?', 'Denitrification', ARRAY['Nitrification', 'Nitrogen fixation', 'Phosphorylation'], 'en', true, 'Denitrification is a bacterial process that converts nitrates into nitrogen gas in wetland soils.'),
('nature', 3, 'What is a desert dust devil?', 'A small rotating column of dust and air', ARRAY['A large sandstorm', 'A haboob', 'A hot wind'], 'en', true, 'Dust devils are small vortexes caused by intense surface heating that lifts dust into a rotating column.'),
('nature', 3, 'What is a lichen composed of?', 'A symbiosis of a fungus and an alga or cyanobacterium', ARRAY['A type of moss', 'A single-celled organism', 'A parasitic fern'], 'en', true, 'Lichens are composite organisms where fungi and photosynthetic algae or cyanobacteria live together.'),
('nature', 3, 'What is the main threat to the coral reefs of New Caledonia?', 'Ocean warming', ARRAY['Net fishing', 'Underwater mining', 'Oil spills'], 'en', true, 'Rising sea temperatures cause bleaching and death of corals in New Caledonian reefs.'),
('nature', 3, 'What biogeochemical cycle recycles nitrogen in soils?', 'The nitrogen cycle', ARRAY['The carbon cycle', 'The phosphorus cycle', 'The sulfur cycle'], 'en', true, 'The nitrogen cycle involves fixation, nitrification, and denitrification in soils and the atmosphere.'),
('nature', 3, 'How does reverse osmosis purify water?', 'By forcing water through a semi-permeable membrane under pressure', ARRAY['By boiling water', 'By adding chlorine', 'By exposing water to UV light'], 'en', true, 'Reverse osmosis uses pressure to push water through a membrane that blocks contaminants and salts.'),
('nature', 3, 'What ocean phenomenon brings cold, nutrient-rich water to the surface?', 'Upwelling', ARRAY['Downwelling', 'Thermocline', 'Drift current'], 'en', true, 'Upwelling brings deep, nutrient-rich water to the surface, supporting productive fisheries and marine life.'),
('nature', 3, 'What type of fungus can decompose wood in a few years?', 'Wood-decay (saprotrophic) fungi', ARRAY['Mycorrhizal fungi', 'Parasitic fungi', 'Endophytic fungi'], 'en', true, 'Saprotrophic fungi produce enzymes that break down lignin and cellulose in dead wood.'),
('nature', 3, 'What is compacted old snow that forms glacier ice called?', 'Firn (neve)', ARRAY['Black ice', 'Frost', 'Snow drift'], 'en', true, 'Firn is granular, partially compacted snow that eventually transforms into solid glacier ice.'),
('nature', 3, 'Which marine ecosystem supports the greatest diversity of fish species?', 'Coral reefs', ARRAY['The open ocean', 'Deep sea vents', 'Mangroves'], 'en', true, 'Coral reefs cover just 0.1% of the ocean floor but support about 25% of all marine species.'),
('nature', 3, 'What causes mirages in the desert?', 'Refraction of light through layers of hot air', ARRAY['Water evaporation', 'Sand reflection', 'Airborne dust'], 'en', true, 'Mirages occur when light bends as it passes through air layers of different temperatures.'),
('nature', 3, 'How do Posidonia seagrass meadows benefit the Mediterranean?', 'They produce oxygen and stabilize the seabed', ARRAY['They warm the water', 'They increase salinity', 'They attract sharks'], 'en', true, 'Posidonia meadows oxygenate the water, stabilize sediments, and provide habitat for marine life.'),
('nature', 3, 'What is albedo and why does it matter in polar regions?', 'It measures how much light a surface reflects; less ice means less reflection and more warming', ARRAY['It measures air temperature', 'It controls ocean currents', 'It regulates polar winds'], 'en', true, 'When ice melts, darker ocean water absorbs more heat, reducing albedo and accelerating warming.'),
('nature', 3, 'What causes massive Saharan dust storms?', 'Powerful winds lifting fine sand particles', ARRAY['Volcanic activity', 'Earthquakes', 'Glacier melting'], 'en', true, 'Strong winds in the Sahara can lift sand and dust high into the atmosphere, reaching Europe and the Americas.'),
('nature', 3, 'How do diatoms help purify water naturally?', 'By filtering and absorbing impurities', ARRAY['By heating the water', 'By increasing salinity', 'By repelling bacteria'], 'en', true, 'Diatoms are siliceous microalgae that filter water and form the base of aquatic food chains.'),
('nature', 3, 'What is the typical pH of peatland soil?', 'Acidic (pH 3-5)', ARRAY['Neutral (pH 7)', 'Alkaline (pH 8-10)', 'Highly alkaline (pH 11-13)'], 'en', true, 'Peatland soils are very acidic due to slow organic decomposition and the presence of sphagnum mosses.'),
('nature', 3, 'What gas trapped in permafrost concerns climate scientists?', 'Methane', ARRAY['Ozone', 'Helium', 'Argon'], 'en', true, 'Thawing permafrost releases methane, a greenhouse gas 80 times more potent than CO2 over 20 years.'),
('nature', 3, 'What type of wind turbine works well in low wind conditions?', 'Vertical axis wind turbine', ARRAY['Offshore wind turbine', 'Three-blade horizontal turbine', 'Concentrated solar turbine'], 'en', true, 'Vertical axis turbines capture wind from all directions and can operate in lighter winds.'),
('nature', 3, 'What role do cyanobacteria play in desert biological crusts?', 'They fix nitrogen and stabilize the soil', ARRAY['They produce salt', 'They warm the sand', 'They repel insects'], 'en', true, 'Cyanobacteria in biological soil crusts bind sand particles and fix atmospheric nitrogen.'),
('nature', 3, 'How do desert plants reduce water loss through their stomata?', 'By opening stomata only at night (CAM metabolism)', ARRAY['By accelerating photosynthesis', 'By absorbing water through leaves', 'By transpiring during the day'], 'en', true, 'CAM plants like cacti open their stomata at night to minimize water loss from evaporation.'),
('nature', 3, 'What advantage do bifacial solar panels have?', 'They capture light on both sides', ARRAY['They are cheaper', 'They work at night', 'They don''t need direct sunlight'], 'en', true, 'Bifacial panels capture direct sunlight on the front and reflected light on the back, increasing efficiency.'),
('nature', 3, 'What organism forms the base of the Antarctic food web?', 'Krill', ARRAY['Phytoplankton only', 'Fish', 'Squid'], 'en', true, 'Antarctic krill (Euphausia superba) is the primary food source for whales, seals, and penguins.'),
('nature', 3, 'Why is Lake Natron in Tanzania red?', 'Halophilic microorganisms produce red pigments', ARRAY['Flamingo blood', 'Volcanic rust', 'Natural red mercury'], 'en', true, 'Halophilic archaea and cyanobacteria thrive in the alkaline water and produce red pigments.'),
('nature', 3, 'How does the Armillaria fungus hold a natural world record?', 'It is the largest known living organism', ARRAY['It is the oldest organism', 'It is the most toxic', 'It grows the fastest'], 'en', true, 'An Armillaria ostoyae in Oregon covers 9.6 square kilometers and may be over 2,400 years old.'),
('nature', 3, 'How do wetlands reduce flood risk?', 'By absorbing and storing excess water like a sponge', ARRAY['By speeding up river flow', 'By blocking rain', 'By accelerating evaporation'], 'en', true, 'Wetlands act as natural retention basins that slow runoff and absorb floodwater.'),
('nature', 3, 'What is the phenomenon of light production by marine dinoflagellates?', 'Bioluminescence', ARRAY['Phosphorescence', 'Fluorescence', 'Chemiluminescence'], 'en', true, 'Dinoflagellates emit blue light when disturbed by waves, creating glowing seas at night.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 3, 'What are submarine meadows that capture carbon called?', 'Seagrass beds', ARRAY['Kelp forests', 'Coral reefs', 'Continental shelves'], 'en', true, 'Seagrass beds capture carbon 35 times faster than tropical forests per unit area.'),
('nature', 3, 'How does natural water filtration through rock purify water?', 'Soil and rock layers trap contaminants as water seeps through', ARRAY['Evaporation alone', 'Freezing kills bacteria', 'Photosynthesis cleans it'], 'en', true, 'As water infiltrates through sand, gravel, and rock layers, impurities are progressively filtered out.'),
('nature', 3, 'What is salt efflorescence on irrigated soils?', 'Crystallized salt rising to the surface due to evaporation', ARRAY['Salt rain from the ocean', 'Underground salt deposits', 'Bacteria producing salt'], 'en', true, 'Evaporation draws dissolved salts to the soil surface where they crystallize, damaging crops.'),
('nature', 3, 'What is mass coral mortality?', 'Widespread coral death from repeated bleaching events', ARRAY['Natural coral aging', 'Coral overgrowth', 'Coral fossilization'], 'en', true, 'Repeated bleaching from warm water temperatures kills large areas of coral reef ecosystems.'),
('nature', 3, 'How do underwater seagrass meadows help fight climate change?', 'They sequester carbon in sediments much faster than forests', ARRAY['They cool the ocean', 'They produce methane that blocks heat', 'They reflect sunlight underwater'], 'en', true, 'Blue carbon ecosystems like seagrass meadows trap carbon in anoxic sediments for centuries.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 4, 'How do ectomycorrhizal fungi transfer phosphorus to tree roots?', 'Through extraradical hyphae that explore soil beyond root reach', ARRAY['By passive root diffusion', 'Through direct leaf absorption', 'Via insect transport'], 'en', true, 'Ectomycorrhizal hyphae extend far into the soil, absorbing phosphorus and delivering it directly to root cells.'),
('nature', 4, 'What ocean phenomenon creates oxygen-depleted dead zones?', 'Eutrophication', ARRAY['Acidification', 'Salinization', 'Thermocline formation'], 'en', true, 'Excess nutrients from agriculture cause algal blooms that consume oxygen when they decompose, creating dead zones.'),
('nature', 4, 'What are organisms that thrive in hot acidic environments called?', 'Thermoacidophiles', ARRAY['Halophiles', 'Psychrophiles', 'Barophiles'], 'en', true, 'Thermoacidophiles are archaea that flourish in extremely hot (>60C) and acidic (pH<3) environments.'),
('nature', 4, 'How do mangroves sequester blue carbon?', 'By accumulating organic matter in anoxic sediments', ARRAY['Through rapid leaf photosynthesis', 'By absorbing CO2 into saltwater', 'Through root calcification'], 'en', true, 'Mangroves trap carbon in oxygen-free sediments where decomposition is extremely slow.'),
('nature', 4, 'What is the daily vertical migration of zooplankton called?', 'Diel vertical migration', ARRAY['Seasonal migration', 'Pelagic movement', 'Planktonic drift'], 'en', true, 'Zooplankton rise to surface waters at night to feed and descend during the day to avoid predators.'),
('nature', 4, 'How do ferralsols form in tropical regions?', 'Through intense chemical weathering under hot, humid conditions', ARRAY['Through repeated freeze-thaw cycles', 'Through salt accumulation', 'Through wind erosion'], 'en', true, 'Ferralsols result from deep chemical weathering that leaves iron and aluminum oxides.'),
('nature', 4, 'What role do fungal endophytes play in grasses?', 'They produce alkaloids that deter herbivores', ARRAY['They color leaves green', 'They speed root growth', 'They attract pollinators'], 'en', true, 'Endophytic fungi living inside grass tissues produce toxins that discourage grazing animals.'),
('nature', 4, 'What drives geyser eruptions in Iceland?', 'Groundwater superheated by magma erupts under pressure', ARRAY['Tides cause water eruptions', 'Wind compresses underground water', 'Glaciers melt and erupt'], 'en', true, 'Water seeps deep underground, gets superheated beyond boiling point by magma, and pressure forces it to the surface.'),
('nature', 4, 'What are ecosystem services provided by wetlands?', 'The total benefits humans derive from wetland ecosystems', ARRAY['The cost of maintaining nature reserves', 'The tourist value of landscapes', 'Agricultural yield from flood plains'], 'en', true, 'Wetland ecosystem services include water purification, flood control, carbon storage, and biodiversity support.'),
('nature', 4, 'How do kelp forests influence the oceanic carbon cycle?', 'By sequestering carbon that sinks to the deep ocean', ARRAY['By releasing CO2 into the atmosphere', 'By preventing plankton photosynthesis', 'By acidifying coastal waters'], 'en', true, 'When kelp fronds die, they sink and transport carbon to the deep ocean floor.'),
('nature', 4, 'What is the ice-albedo feedback loop in the Arctic?', 'Ice loss reduces reflectivity, which accelerates warming and more ice loss', ARRAY['Ice increases by reflecting more heat', 'Clouds cool the ice surface', 'Fresh snow absorbs more heat'], 'en', true, 'Less ice means darker ocean surfaces absorb more solar radiation, causing more warming and more melting.'),
('nature', 4, 'What extremophile was discovered in the Mariana Trench?', 'Piezophilic (barophilic) bacteria', ARRAY['Giant deep-sea fish', 'Deep corals', 'Bioluminescent algae'], 'en', true, 'Piezophilic bacteria thrive under the extreme pressures found in deep ocean trenches.'),
('nature', 4, 'How is the fungus Trichoderma used in sustainable agriculture?', 'As a biocontrol agent against soil pathogens', ARRAY['As a natural chemical fertilizer', 'As a spray pesticide', 'As earthworm food'], 'en', true, 'Trichoderma fungi parasitize plant pathogens and stimulate plant immune defenses.'),
('nature', 4, 'What is phytoremediation?', 'Using plants to absorb or degrade soil pollutants', ARRAY['Burning contaminated vegetation', 'Flooding soil to dilute pollutants', 'Covering soil with concrete'], 'en', true, 'Hyperaccumulator plants can extract heavy metals from contaminated soil through their roots.'),
('nature', 4, 'How does the termite mound cooling system work?', 'Through natural ventilation via internal tunnels and chimneys', ARRAY['By producing underground ice', 'By using wet leaves', 'By reflecting sunlight'], 'en', true, 'Termite mounds have complex tunnel systems that create natural air circulation to regulate temperature.'),
('nature', 4, 'What role does permafrost play in Earth''s radiative budget?', 'It stores organic carbon that amplifies warming when released', ARRAY['It absorbs UV rays', 'It reflects radio waves', 'It blocks cosmic rays'], 'en', true, 'Permafrost contains about 1,500 gigatons of organic carbon whose release would accelerate climate change.'),
('nature', 4, 'How do mesophotic coral reefs differ from shallow reefs?', 'They exist between 30-150m depth with reduced light', ARRAY['They are more colorful and diverse', 'They have no polyps', 'They consist only of soft coral'], 'en', true, 'Mesophotic reefs receive limited light and harbor species adapted to low-light conditions.'),
('nature', 4, 'What geochemical phenomenon explains the blue color of Lake Pukaki?', 'Glacial rock flour suspended in the water', ARRAY['Blue algae', 'Sky reflection', 'White limestone bottom'], 'en', true, 'Fine rock particles ground by glaciers scatter light, giving the lake its distinctive turquoise color.'),
('nature', 4, 'How do endomycorrhizal fungi penetrate root cells?', 'By forming arbuscules inside cortical cells', ARRAY['By piercing cell walls with acid enzymes', 'By attaching to root surfaces', 'By entering through leaf stomata'], 'en', true, 'Endomycorrhizal fungi form branched arbuscules inside root cells to exchange nutrients and sugars.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 5, 'How do tardigrades survive complete desiccation at the molecular level?', 'TDP proteins replace water and vitrify cells', ARRAY['Glycerol antifreeze production', 'Chitin shell encapsulation', 'Metabolic hibernation only'], 'en', true, 'Tardigrade-specific Disordered Proteins form a glass-like matrix that protects cellular structures during dehydration.'),
('nature', 5, 'How does the fungus Ophiocordyceps unilateralis control ant behavior?', 'By secreting metabolites that alter the ant''s nervous system', ARRAY['By blocking the ant''s eyes', 'By emitting ultrasound', 'By modifying the ant''s DNA'], 'en', true, 'This parasitic fungus chemically manipulates ants to climb high and bite a leaf, optimizing spore dispersal.'),
('nature', 5, 'What is extinction debt in conservation ecology?', 'Future extinctions already determined by past habitat degradation', ARRAY['The number of past extinctions', 'The financial cost of species protection', 'The number of uncontrolled invasive species'], 'en', true, 'Extinction debt refers to species that will inevitably go extinct due to habitat fragmentation that has already occurred.'),
('nature', 5, 'How does carbon mineralization work in Oman''s peridotites?', 'CO2 reacts with magnesium silicates to form solid carbonates', ARRAY['Underground algae absorb the carbon', 'Desert heat vaporizes CO2', 'Bacteria convert CO2 to methane'], 'en', true, 'Peridotite rocks react naturally with atmospheric CO2 to form magnesite, permanently sequestering carbon.'),
('nature', 5, 'What role do biogenic volatile organic compounds (BVOCs) from forests play?', 'They form aerosols that nucleate clouds and influence climate', ARRAY['They repel all insects', 'They destroy the ozone layer', 'They acidify forest soils'], 'en', true, 'BVOCs like isoprene and terpenes oxidize into secondary organic aerosols that act as cloud condensation nuclei.'),
('nature', 5, 'How do hadal zone fish withstand pressures exceeding 1,000 atmospheres?', 'TMAO (trimethylamine N-oxide) stabilizes their proteins', ARRAY['Calcium-reinforced bones', 'Cartilage-armored skin', 'Total anaerobic metabolism'], 'en', true, 'TMAO counteracts the pressure-induced deformation of proteins, allowing enzymes to function normally at extreme depth.'),
('nature', 5, 'What is the biological carbon pump in the ocean?', 'Transfer of carbon fixed by phytoplankton to deep waters via sinking organic matter', ARRAY['CO2 release from submarine volcanoes', 'Limestone dissolution in seawater', 'Deep-sea algae photosynthesis'], 'en', true, 'Phytoplankton fix CO2 at the surface; fecal pellets and dead organisms sink, exporting carbon to the deep ocean.'),
('nature', 5, 'How does the mycorrhizal network enable kin recognition in trees?', 'Mother trees transfer more carbon to seedlings of their own species via fungal networks', ARRAY['Trees communicate via root ultrasound', 'Fallen leaves selectively feed offspring', 'Roots fuse genetically'], 'en', true, 'Suzanne Simard''s research showed mother trees preferentially support their own seedlings through mycorrhizal carbon and defense signals.'),
('nature', 5, 'What is the clathrate gun hypothesis regarding oceanic methane?', 'Warming could destabilize seafloor methane hydrates, releasing massive CH4', ARRAY['Submarine volcanoes emit methane continuously', 'Surface methanogenic bacteria multiply', 'Icebergs contain methane pockets'], 'en', true, 'Methane clathrates are ice structures trapping CH4 that could destabilize if ocean floors warm sufficiently.'),
('nature', 5, 'How do Nostoc cyanobacteria fix atmospheric nitrogen?', 'Via heterocysts that maintain an anaerobic environment for nitrogenase', ARRAY['Through modified photosynthesis in all cells', 'By absorbing soil nitrates', 'By capturing nitrogen with extracellular pili'], 'en', true, 'Heterocysts are thick-walled specialized cells that protect the oxygen-sensitive nitrogenase enzyme.'),
('nature', 5, 'What is the mechanism of weathering enhancement by mycorrhizal fungi?', 'Hyphae secrete organic acids that dissolve rock minerals', ARRAY['Fungi heat rocks through fermentation', 'Spores infiltrate cracks and shatter rock', 'Mycelia absorb moisture and freeze the rock'], 'en', true, 'Fungal organic acids and enzymes dissolve minerals from rocks, releasing phosphorus and potassium for plants.'),
('nature', 5, 'How do deep cold-water corals feed without photosynthesis?', 'By capturing suspended organic particles from ocean currents', ARRAY['Through symbiosis with sulfur bacteria', 'By direct absorption of dissolved nutrients', 'By actively preying on small fish'], 'en', true, 'Cold-water corals are filter feeders that capture zooplankton and organic matter carried by currents.'),
('nature', 5, 'What is the tipping point concept for the Amazon rainforest?', 'A deforestation threshold beyond which the forest irreversibly converts to savanna', ARRAY['The moment the forest reaches maximum size', 'The season when trees shed leaves', 'The CO2 saturation point of trees'], 'en', true, 'Scientists estimate that 20-25% deforestation could trigger irreversible drying and conversion of the Amazon to savanna.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 1, 'Quelle est la capitale de la Croatie ?', 'Zagreb', ARRAY['Belgrade', 'Ljubljana', 'Sarajevo'], 'fr', true, 'Zagreb est la capitale et la plus grande ville de Croatie, située au nord du pays.'),
('geography', 1, 'Quel est le plus grand pays d''Afrique par superficie ?', 'L''Algérie', ARRAY['Le Soudan', 'La République démocratique du Congo', 'La Libye'], 'fr', true, 'L''Algérie est le plus grand pays d''Afrique avec 2,38 millions de km².'),
('geography', 1, 'Quelle île est la plus grande du monde ?', 'Le Groenland', ARRAY['Madagascar', 'Bornéo', 'La Nouvelle-Guinée'], 'fr', true, 'Le Groenland couvre environ 2,16 millions de km², c''est la plus grande île du monde (l''Australie étant un continent).'),
('geography', 1, 'Quelle est la capitale du Cambodge ?', 'Phnom Penh', ARRAY['Siem Reap', 'Bangkok', 'Hanoï'], 'fr', true, 'Phnom Penh est la capitale du Cambodge, située au confluent du Mékong et du Tonlé Sap.'),
('geography', 1, 'Quel pays possède le drapeau tricolore vert, blanc et rouge (vertical) ?', 'L''Italie', ARRAY['La Hongrie', 'L''Irlande', 'Le Mexique'], 'fr', true, 'Le drapeau italien est composé de trois bandes verticales verte, blanche et rouge.'),
('geography', 1, 'Quel fleuve traverse le Vietnam et le Cambodge ?', 'Le Mékong', ARRAY['Le Yangtsé', 'Le Gange', 'L''Irrawaddy'], 'fr', true, 'Le Mékong est l''un des plus grands fleuves d''Asie du Sud-Est, traversant six pays.'),
('geography', 1, 'Quelle est la monnaie officielle du Royaume-Uni ?', 'La livre sterling', ARRAY['L''euro', 'Le dollar', 'Le franc'], 'fr', true, 'La livre sterling est la monnaie du Royaume-Uni depuis des siècles.'),
('geography', 1, 'Quel est le plus petit pays d''Amérique du Sud par superficie ?', 'Le Suriname', ARRAY['L''Uruguay', 'Le Guyana', 'L''Équateur'], 'fr', true, 'Le Suriname est le plus petit pays souverain d''Amérique du Sud avec 163 820 km².'),
('geography', 1, 'Quelle mer intérieure se trouve entre l''Europe et l''Asie ?', 'La mer Noire', ARRAY['La mer Rouge', 'La mer Caspienne', 'La mer Baltique'], 'fr', true, 'La mer Noire borde la Turquie, la Bulgarie, la Roumanie, l''Ukraine, la Russie et la Géorgie.'),
('geography', 1, 'Quelle est la capitale de la Roumanie ?', 'Bucarest', ARRAY['Budapest', 'Sofia', 'Belgrade'], 'fr', true, 'Bucarest est la capitale de la Roumanie, surnommée le petit Paris des Balkans.'),
('geography', 1, 'Quel pays est connu comme le pays du long nuage blanc ?', 'La Nouvelle-Zélande', ARRAY['L''Australie', 'L''Islande', 'La Norvège'], 'fr', true, 'La Nouvelle-Zélande est appelée Aotearoa en maori, ce qui signifie le pays du long nuage blanc.'),
('geography', 1, 'Quel détroit sépare l''Europe de l''Asie à Istanbul ?', 'Le Bosphore', ARRAY['Le détroit de Gibraltar', 'Les Dardanelles', 'Le canal de Suez'], 'fr', true, 'Le Bosphore est un détroit de 32 km qui relie la mer de Marmara à la mer Noire.'),
('geography', 1, 'Quelle est la capitale du Sénégal ?', 'Dakar', ARRAY['Bamako', 'Conakry', 'Abidjan'], 'fr', true, 'Dakar est la capitale du Sénégal, située à l''extrémité ouest de l''Afrique.'),
('geography', 1, 'Quel pays a la plus grande population d''Europe ?', 'La Russie', ARRAY['L''Allemagne', 'La France', 'Le Royaume-Uni'], 'fr', true, 'La Russie a la plus grande population européenne avec environ 145 millions d''habitants (partie européenne).'),
('geography', 1, 'Quelle est la capitale des Philippines ?', 'Manille', ARRAY['Cebu', 'Davao', 'Jakarta'], 'fr', true, 'Manille est la capitale des Philippines, un archipel de plus de 7 600 îles.'),
('geography', 1, 'Quel fleuve traverse Bagdad ?', 'Le Tigre', ARRAY['L''Euphrate', 'Le Nil', 'Le Jourdain'], 'fr', true, 'Le Tigre traverse Bagdad, la capitale de l''Irak, avant de rejoindre l''Euphrate.'),
('geography', 1, 'Quelle île française se trouve dans l''océan Indien ?', 'La Réunion', ARRAY['La Guadeloupe', 'La Martinique', 'Saint-Pierre-et-Miquelon'], 'fr', true, 'La Réunion est un département d''outre-mer français situé dans l''océan Indien, près de Madagascar.'),
('geography', 1, 'Quelle est la capitale de l''Arabie saoudite ?', 'Riyad', ARRAY['La Mecque', 'Djeddah', 'Médine'], 'fr', true, 'Riyad est la capitale et la plus grande ville d''Arabie saoudite.'),
('geography', 1, 'Quel pays d''Asie est constitué de plus de 17 000 îles ?', 'L''Indonésie', ARRAY['Les Philippines', 'Le Japon', 'La Malaisie'], 'fr', true, 'L''Indonésie est le plus grand archipel du monde avec plus de 17 000 îles.'),
('geography', 1, 'Quelle est la capitale de la Bulgarie ?', 'Sofia', ARRAY['Bucarest', 'Belgrade', 'Athènes'], 'fr', true, 'Sofia est la capitale de la Bulgarie, située au pied du mont Vitosha.'),
('geography', 1, 'Quel site UNESCO célèbre se trouve au Pérou ?', 'Le Machu Picchu', ARRAY['Chichén Itzá', 'Les îles Galápagos', 'La cité de Petra'], 'fr', true, 'Le Machu Picchu est une ancienne cité inca perchée à 2 430 m d''altitude dans les Andes péruviennes.'),
('geography', 1, 'Quel pays européen a pour drapeau une croix blanche sur fond rouge ?', 'La Suisse', ARRAY['Le Danemark', 'La Suède', 'La Norvège'], 'fr', true, 'Le drapeau suisse est un carré rouge avec une croix blanche au centre.'),
('geography', 1, 'Quelle rivière traverse le Grand Canyon aux États-Unis ?', 'Le Colorado', ARRAY['Le Mississippi', 'Le Missouri', 'Le Rio Grande'], 'fr', true, 'Le fleuve Colorado a creusé le Grand Canyon sur une profondeur de plus de 1 600 mètres.'),
('geography', 1, 'Quelle est la capitale de la République tchèque ?', 'Prague', ARRAY['Bratislava', 'Varsovie', 'Vienne'], 'fr', true, 'Prague est la capitale de la République tchèque, célèbre pour son architecture médiévale.'),
('geography', 1, 'Quel pays africain a pour capitale Addis-Abeba ?', 'L''Éthiopie', ARRAY['Le Kenya', 'La Somalie', 'L''Érythrée'], 'fr', true, 'Addis-Abeba est la capitale de l''Éthiopie et le siège de l''Union africaine.'),
('geography', 1, 'Quel est le plus long fleuve d''Asie ?', 'Le Yangtsé', ARRAY['Le Mékong', 'Le Gange', 'L''Ob'], 'fr', true, 'Le Yangtsé (Chang Jiang) mesure 6 300 km et traverse la Chine d''ouest en est.'),
('geography', 1, 'Quelle ville est surnommée la Perle de l''Orient ?', 'Shanghai', ARRAY['Hong Kong', 'Tokyo', 'Singapour'], 'fr', true, 'Shanghai est surnommée la Perle de l''Orient pour sa skyline spectaculaire et son dynamisme économique.'),
('geography', 1, 'Quelle est la capitale de l''Ukraine ?', 'Kiev', ARRAY['Odessa', 'Kharkiv', 'Lviv'], 'fr', true, 'Kiev (Kyiv) est la capitale de l''Ukraine, située sur les rives du Dniepr.'),
('geography', 1, 'Quel pays possède le plus de volcans actifs au monde ?', 'L''Indonésie', ARRAY['Le Japon', 'L''Islande', 'L''Italie'], 'fr', true, 'L''Indonésie compte environ 130 volcans actifs, le plus grand nombre au monde.'),
('geography', 1, 'Quelle est la capitale de la Finlande ?', 'Helsinki', ARRAY['Stockholm', 'Oslo', 'Tallinn'], 'fr', true, 'Helsinki est la capitale de la Finlande, située sur la côte sud du pays.'),
('geography', 1, 'Quel pays est traversé par le Nil Bleu et le Nil Blanc ?', 'Le Soudan', ARRAY['L''Égypte', 'L''Éthiopie', 'L''Ouganda'], 'fr', true, 'Le Nil Bleu et le Nil Blanc se rejoignent à Khartoum, la capitale du Soudan.'),
('geography', 1, 'Quelle est la monnaie utilisée dans la zone euro ?', 'L''euro', ARRAY['Le dollar', 'La livre sterling', 'Le franc suisse'], 'fr', true, 'L''euro est la monnaie commune de 20 pays de l''Union européenne.'),
('geography', 1, 'Quel pays d''Amérique latine a pour capitale Lima ?', 'Le Pérou', ARRAY['La Colombie', 'L''Équateur', 'Le Chili'], 'fr', true, 'Lima est la capitale du Pérou, fondée en 1535 par Francisco Pizarro.'),
('geography', 1, 'Quelle montagne est le point culminant du Japon ?', 'Le mont Fuji', ARRAY['Le mont Asahi', 'Le mont Aso', 'Le mont Hotaka'], 'fr', true, 'Le mont Fuji culmine à 3 776 m et est le symbole le plus reconnaissable du Japon.'),
('geography', 1, 'Quelle est la capitale du Pakistan ?', 'Islamabad', ARRAY['Karachi', 'Lahore', 'Rawalpindi'], 'fr', true, 'Islamabad est la capitale du Pakistan depuis 1967, construite spécifiquement pour ce rôle.'),
('geography', 1, 'Quel pays est situé entre la Chine et la Russie en Asie centrale ?', 'La Mongolie', ARRAY['Le Kazakhstan', 'Le Kirghizistan', 'Le Tadjikistan'], 'fr', true, 'La Mongolie est un vaste pays enclavé entre la Chine au sud et la Russie au nord.'),
('geography', 1, 'Quelle est la plus grande île de la mer des Caraïbes ?', 'Cuba', ARRAY['Hispaniola', 'La Jamaïque', 'Porto Rico'], 'fr', true, 'Cuba est la plus grande île des Caraïbes avec environ 110 000 km² de superficie.'),
('geography', 1, 'Quel pays possède le drapeau avec un soleil rouge sur fond blanc ?', 'Le Japon', ARRAY['La Corée du Sud', 'Le Bangladesh', 'Le Laos'], 'fr', true, 'Le drapeau japonais (Hinomaru) représente un disque rouge symbolisant le soleil sur fond blanc.'),
('geography', 1, 'Quelle capitale européenne est traversée par la Vltava (Moldau) ?', 'Prague', ARRAY['Vienne', 'Budapest', 'Bratislava'], 'fr', true, 'La Vltava traverse Prague, la capitale de la République tchèque, où elle est enjambée par le célèbre Pont Charles.'),
('geography', 1, 'Quel pays d''Océanie est un archipel de 33 atolls ?', 'Les Kiribati', ARRAY['Les Tonga', 'Les Fidji', 'Samoa'], 'fr', true, 'Les Kiribati sont un État insulaire du Pacifique central composé de 33 atolls coralliens.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 1, 'Quelle est la capitale de la Jordanie ?', 'Amman', ARRAY['Beyrouth', 'Damas', 'Bagdad'], 'fr', true, 'Amman est la capitale de la Jordanie, une ville moderne bâtie sur sept collines.'),
('geography', 1, 'Quel est le plus haut sommet d''Amérique du Sud ?', 'L''Aconcagua', ARRAY['Le Chimborazo', 'Le Cotopaxi', 'L''Huascarán'], 'fr', true, 'L''Aconcagua, en Argentine, culmine à 6 961 m et est le plus haut sommet des Amériques.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 2, 'Quel pays produit le plus de café au monde ?', 'Le Brésil', ARRAY['La Colombie', 'Le Vietnam', 'L''Éthiopie'], 'fr', true, 'Le Brésil est le premier producteur mondial de café depuis plus de 150 ans.'),
('geography', 2, 'Quelle est la plus haute tour du monde en 2024 ?', 'Le Burj Khalifa', ARRAY['La Shanghai Tower', 'L''Abraj Al-Bait', 'La Lotte World Tower'], 'fr', true, 'Le Burj Khalifa à Dubaï mesure 828 mètres de hauteur, c''est le plus haut gratte-ciel du monde.'),
('geography', 2, 'Quel pays a le plus grand nombre de sites UNESCO au monde ?', 'L''Italie', ARRAY['La Chine', 'L''Espagne', 'La France'], 'fr', true, 'L''Italie possède le plus grand nombre de sites classés au patrimoine mondial de l''UNESCO.'),
('geography', 2, 'Quelle ville est surnommée la Cité des Anges ?', 'Bangkok', ARRAY['Los Angeles', 'Rome', 'Rio de Janeiro'], 'fr', true, 'Le nom complet de Bangkok en thaï signifie la cité des anges, tout comme Los Angeles en espagnol.'),
('geography', 2, 'Quel est le seul pays au monde traversé par l''équateur et le tropique du Capricorne ?', 'Le Brésil', ARRAY['L''Indonésie', 'La Colombie', 'Le Kenya'], 'fr', true, 'Le Brésil est assez grand pour être traversé à la fois par l''équateur au nord et le tropique du Capricorne au sud.'),
('geography', 2, 'Quel est le plus long pont maritime du monde ?', 'Le pont Hong Kong-Zhuhai-Macao', ARRAY['Le pont Akashi-Kaikyō', 'Le pont de Crimée', 'Le pont du lac Pontchartrain'], 'fr', true, 'Le pont Hong Kong-Zhuhai-Macao mesure 55 km et traverse l''estuaire de la rivière des Perles.'),
('geography', 2, 'Quelle est la capitale du Laos ?', 'Vientiane', ARRAY['Luang Prabang', 'Phnom Penh', 'Rangoun'], 'fr', true, 'Vientiane est la capitale du Laos, située sur les rives du Mékong, face à la Thaïlande.'),
('geography', 2, 'Quel pays possède la plus longue frontière terrestre au monde ?', 'Le Canada', ARRAY['La Russie', 'La Chine', 'Le Brésil'], 'fr', true, 'La frontière entre le Canada et les États-Unis mesure 8 891 km, la plus longue frontière terrestre.'),
('geography', 2, 'Quelle ville est bâtie sur 118 petites îles reliées par des ponts ?', 'Venise', ARRAY['Amsterdam', 'Stockholm', 'Bruges'], 'fr', true, 'Venise est construite sur 118 îlots dans la lagune de Venise, reliés par environ 400 ponts.'),
('geography', 2, 'Quel pays d''Afrique est enclavé (sans accès à la mer) et célèbre pour ses gorilles ?', 'Le Rwanda', ARRAY['L''Ouganda', 'Le Burundi', 'La République centrafricaine'], 'fr', true, 'Le Rwanda est un petit pays enclavé d''Afrique de l''Est, connu pour ses gorilles de montagne.'),
('geography', 2, 'Quelle est la capitale de la Birmanie (Myanmar) ?', 'Naypyidaw', ARRAY['Rangoun', 'Mandalay', 'Bagan'], 'fr', true, 'Naypyidaw est la capitale administrative de la Birmanie depuis 2006, remplaçant Rangoun.'),
('geography', 2, 'Quel pays européen possède le littoral le plus long ?', 'La Norvège', ARRAY['La Grèce', 'Le Royaume-Uni', 'L''Italie'], 'fr', true, 'La Norvège possède un littoral d''environ 25 000 km grâce à ses milliers de fjords.'),
('geography', 2, 'Quel pays est le premier producteur mondial de riz ?', 'La Chine', ARRAY['L''Inde', 'L''Indonésie', 'Le Bangladesh'], 'fr', true, 'La Chine est le premier producteur mondial de riz avec environ 210 millions de tonnes par an.'),
('geography', 2, 'Quelle chaîne de montagnes contient le plus haut sommet du monde ?', 'L''Himalaya', ARRAY['Les Andes', 'Les Alpes', 'Les Rocheuses'], 'fr', true, 'L''Himalaya abrite l''Everest (8 849 m) et 13 des 14 sommets de plus de 8 000 m.'),
('geography', 2, 'Quelle ville est la plus peuplée d''Afrique ?', 'Lagos', ARRAY['Le Caire', 'Kinshasa', 'Nairobi'], 'fr', true, 'Lagos, au Nigeria, est la ville la plus peuplée d''Afrique avec plus de 15 millions d''habitants.'),
('geography', 2, 'Quel archipel espagnol se trouve au large de l''Afrique du Nord ?', 'Les îles Canaries', ARRAY['Les Baléares', 'Les Açores', 'Madère'], 'fr', true, 'Les îles Canaries sont un archipel espagnol situé au large du Maroc et du Sahara occidental.'),
('geography', 2, 'Quel pays d''Amérique centrale a deux côtes océaniques et pas d''armée ?', 'Le Costa Rica', ARRAY['Le Panama', 'Le Honduras', 'Le Nicaragua'], 'fr', true, 'Le Costa Rica a aboli son armée en 1949 et est bordé par le Pacifique et les Caraïbes.'),
('geography', 2, 'Quelle est la capitale du Kenya ?', 'Nairobi', ARRAY['Mombasa', 'Dar es Salaam', 'Kampala'], 'fr', true, 'Nairobi est la capitale du Kenya et un centre économique majeur d''Afrique de l''Est.'),
('geography', 2, 'Quel pays possède les chutes d''Iguazú avec l''Argentine ?', 'Le Brésil', ARRAY['Le Paraguay', 'L''Uruguay', 'Le Chili'], 'fr', true, 'Les chutes d''Iguazú se trouvent à la frontière entre le Brésil et l''Argentine.'),
('geography', 2, 'Quelle est la capitale de la Malaisie ?', 'Kuala Lumpur', ARRAY['Singapour', 'Jakarta', 'Manille'], 'fr', true, 'Kuala Lumpur est la capitale de la Malaisie, connue pour ses tours Petronas.'),
('geography', 2, 'Quel pays produit le plus de pétrole au monde ?', 'Les États-Unis', ARRAY['L''Arabie saoudite', 'La Russie', 'Le Canada'], 'fr', true, 'Les États-Unis sont devenus le premier producteur mondial de pétrole grâce au pétrole de schiste.'),
('geography', 2, 'Quel site UNESCO se trouve dans le sud de la Jordanie ?', 'Petra', ARRAY['Jérash', 'Aqaba', 'Madaba'], 'fr', true, 'Petra est une cité antique taillée dans la roche rose, l''une des sept nouvelles merveilles du monde.'),
('geography', 2, 'Quelle est la capitale de la Serbie ?', 'Belgrade', ARRAY['Zagreb', 'Sarajevo', 'Podgorica'], 'fr', true, 'Belgrade est la capitale de la Serbie, située au confluent du Danube et de la Save.'),
('geography', 2, 'Quel pays possède le plus grand réseau ferroviaire au monde ?', 'Les États-Unis', ARRAY['La Chine', 'La Russie', 'L''Inde'], 'fr', true, 'Les États-Unis possèdent le plus grand réseau ferroviaire au monde avec environ 250 000 km de voies.'),
('geography', 2, 'Quelle ville est partagée entre deux continents ?', 'Istanbul', ARRAY['Le Caire', 'Moscou', 'Singapour'], 'fr', true, 'Istanbul est à cheval sur l''Europe et l''Asie, séparées par le détroit du Bosphore.'),
('geography', 2, 'Quel fleuve forme une partie de la frontière entre les États-Unis et le Mexique ?', 'Le Rio Grande', ARRAY['Le Colorado', 'Le Mississippi', 'Le Potomac'], 'fr', true, 'Le Rio Grande (Río Bravo) forme la frontière entre le Texas et le Mexique.'),
('geography', 2, 'Quelle est la capitale du Bangladesh ?', 'Dacca', ARRAY['Chittagong', 'Khulna', 'Rangpur'], 'fr', true, 'Dacca (Dhaka) est la capitale du Bangladesh, l''une des villes les plus densément peuplées au monde.'),
('geography', 2, 'Quel pays insulaire de l''océan Indien est célèbre pour ses lémuriens ?', 'Madagascar', ARRAY['Les Maldives', 'Les Seychelles', 'L''île Maurice'], 'fr', true, 'Madagascar est le seul endroit au monde où vivent les lémuriens à l''état sauvage.'),
('geography', 2, 'Quel est le plus grand lac d''Amérique du Sud ?', 'Le lac Titicaca', ARRAY['Le lac Maracaibo', 'Le lac Buenos Aires', 'Le lac Poopó'], 'fr', true, 'Le lac Titicaca, partagé entre le Pérou et la Bolivie, est le plus grand lac d''Amérique du Sud par volume.'),
('geography', 2, 'Quelle est la capitale du Ghana ?', 'Accra', ARRAY['Lagos', 'Abidjan', 'Lomé'], 'fr', true, 'Accra est la capitale du Ghana, un pays d''Afrique de l''Ouest sur le golfe de Guinée.'),
('geography', 2, 'Quel pays a trois langues officielles : allemand, français et italien ?', 'La Suisse', ARRAY['La Belgique', 'Le Luxembourg', 'L''Autriche'], 'fr', true, 'La Suisse a quatre langues nationales : allemand, français, italien et romanche.'),
('geography', 2, 'Quel pays possède le fjord le plus long du monde ?', 'La Norvège', ARRAY['Le Chili', 'Le Canada', 'La Nouvelle-Zélande'], 'fr', true, 'Le Sognefjord en Norvège mesure 204 km de long et 1 308 m de profondeur.'),
('geography', 2, 'Quelle est la ville la plus peuplée d''Amérique du Sud ?', 'São Paulo', ARRAY['Buenos Aires', 'Rio de Janeiro', 'Bogota'], 'fr', true, 'São Paulo au Brésil est la plus grande ville d''Amérique du Sud avec plus de 12 millions d''habitants (22 millions en agglomération).'),
('geography', 2, 'Quel pays est situé entièrement au-dessus de 1 000 m d''altitude ?', 'Le Lesotho', ARRAY['La Suisse', 'Le Népal', 'Le Bhoutan'], 'fr', true, 'Le Lesotho est le seul pays au monde dont tout le territoire se trouve au-dessus de 1 000 mètres d''altitude.'),
('geography', 2, 'Quel détroit relie la mer Méditerranée à la mer Noire ?', 'Les Dardanelles et le Bosphore', ARRAY['Le détroit de Gibraltar', 'Le canal de Suez', 'Le détroit de Messine'], 'fr', true, 'La Méditerranée est reliée à la mer Noire via les Dardanelles, la mer de Marmara et le Bosphore.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 3, 'Quel pays a pour capitale Oulan-Bator ?', 'La Mongolie', ARRAY['Le Kazakhstan', 'Le Kirghizistan', 'Le Turkménistan'], 'fr', true, 'Oulan-Bator est la capitale de la Mongolie, où vit près de la moitié de la population du pays.'),
('geography', 3, 'Quelle île est partagée entre trois pays : Indonésie, Malaisie et Brunei ?', 'Bornéo', ARRAY['Sumatra', 'Java', 'Célèbes'], 'fr', true, 'Bornéo est la troisième plus grande île du monde, partagée entre l''Indonésie, la Malaisie et Brunei.'),
('geography', 3, 'Quel pays possède la plus grande réserve de lithium au monde ?', 'La Bolivie', ARRAY['L''Australie', 'Le Chili', 'L''Argentine'], 'fr', true, 'Le salar d''Uyuni en Bolivie contient les plus grandes réserves de lithium connues au monde.'),
('geography', 3, 'Quelle est la ville la plus au nord du monde avec plus de 100 000 habitants ?', 'Mourmansk', ARRAY['Tromsø', 'Reykjavik', 'Anchorage'], 'fr', true, 'Mourmansk, en Russie, est la plus grande ville au nord du cercle arctique avec environ 280 000 habitants.'),
('geography', 3, 'Quel pays d''Afrique est traversé par le méridien de Greenwich et l''équateur ?', 'Le Ghana', ARRAY['Le Gabon', 'Le Cameroun', 'Le Togo'], 'fr', true, 'Le Ghana est le seul pays au monde traversé à la fois par le méridien de Greenwich et l''équateur (très proche).'),
('geography', 3, 'Quel pays est le plus grand exportateur de diamants au monde ?', 'La Russie', ARRAY['Le Botswana', 'L''Afrique du Sud', 'L''Angola'], 'fr', true, 'La Russie est le premier producteur mondial de diamants bruts, principalement en Yakoutie.'),
('geography', 3, 'Quelle est la capitale du Bhoutan ?', 'Thimphou', ARRAY['Katmandou', 'Dacca', 'Colombo'], 'fr', true, 'Thimphou est la capitale du Bhoutan, un petit royaume himalayen qui mesure son bonheur national brut.'),
('geography', 3, 'Quel fleuve européen traverse le plus grand nombre de capitales ?', 'Le Danube', ARRAY['Le Rhin', 'La Seine', 'La Tamise'], 'fr', true, 'Le Danube traverse quatre capitales : Vienne, Bratislava, Budapest et Belgrade.'),
('geography', 3, 'Quelle île volcanique islandaise est née d''une éruption sous-marine en 1963 ?', 'Surtsey', ARRAY['Heimaey', 'Grimsey', 'Flatey'], 'fr', true, 'Surtsey est née d''une éruption sous-marine entre 1963 et 1967 au sud de l''Islande, site UNESCO depuis 2008.'),
('geography', 3, 'Quel pays possède le plus de parcs nationaux au monde ?', 'L''Australie', ARRAY['Les États-Unis', 'Le Brésil', 'La Chine'], 'fr', true, 'L''Australie possède plus de 500 parcs nationaux répartis sur tout le continent.'),
('geography', 3, 'Quel est le point le plus éloigné de tout océan sur Terre ?', 'Le pôle continental d''inaccessibilité en Asie centrale', ARRAY['Le centre du Sahara', 'Le Tibet', 'Le centre de l''Australie'], 'fr', true, 'Le point le plus éloigné de tout océan se trouve au nord-ouest de la Chine, à environ 2 645 km de la côte la plus proche.'),
('geography', 3, 'Quelle ville africaine est surnommée la ville blanche ?', 'Alger', ARRAY['Casablanca', 'Tunis', 'Le Caire'], 'fr', true, 'Alger est surnommée El-Bahdja (la Radieuse) ou la ville blanche en raison de ses bâtiments blancs.'),
('geography', 3, 'Quel pays d''Amérique du Sud a deux capitales officielles ?', 'La Bolivie', ARRAY['Le Pérou', 'L''Équateur', 'Le Paraguay'], 'fr', true, 'La Bolivie a Sucre comme capitale constitutionnelle et La Paz comme siège du gouvernement.'),
('geography', 3, 'Quelle île est la plus grande du Japon ?', 'Honshū', ARRAY['Hokkaidō', 'Kyūshū', 'Shikoku'], 'fr', true, 'Honshū est la plus grande île du Japon avec 227 960 km², abritant Tokyo, Osaka et Kyoto.'),
('geography', 3, 'Quel pays a la plus forte densité de population au monde ?', 'Monaco', ARRAY['Singapour', 'Le Vatican', 'Malte'], 'fr', true, 'Monaco a une densité d''environ 26 000 habitants au km², la plus élevée au monde.'),
('geography', 3, 'Quel site UNESCO abrite les célèbres statues Moaï ?', 'L''île de Pâques (Rapa Nui)', ARRAY['Les Galápagos', 'Hawaï', 'Les Tonga'], 'fr', true, 'L''île de Pâques, territoire chilien dans le Pacifique, est célèbre pour ses 887 statues monumentales Moaï.'),
('geography', 3, 'Quel pays européen possède le plus de lacs ?', 'La Finlande', ARRAY['La Suède', 'La Norvège', 'La Russie'], 'fr', true, 'La Finlande possède environ 188 000 lacs, d''où son surnom de pays des mille lacs.'),
('geography', 3, 'Quelle ville est la plus haute capitale du monde ?', 'La Paz (Bolivie)', ARRAY['Quito (Équateur)', 'Bogota (Colombie)', 'Addis-Abeba (Éthiopie)'], 'fr', true, 'La Paz se situe à environ 3 640 m d''altitude, ce qui en fait la capitale de facto la plus haute du monde.'),
('geography', 3, 'Quel est le seul pays au monde dont le drapeau n''est pas rectangulaire ?', 'Le Népal', ARRAY['La Suisse', 'Le Vatican', 'Le Bhoutan'], 'fr', true, 'Le drapeau du Népal est composé de deux triangles superposés, une forme unique au monde.'),
('geography', 3, 'Quel pays a la plus grande forêt boréale (taïga) du monde ?', 'La Russie', ARRAY['Le Canada', 'La Finlande', 'La Suède'], 'fr', true, 'La taïga russe est la plus grande forêt du monde, couvrant environ 12 millions de km².'),
('geography', 3, 'Quelle capitale d''Asie du Sud-Est se trouve sur le fleuve Chao Phraya ?', 'Bangkok', ARRAY['Hanoï', 'Phnom Penh', 'Jakarta'], 'fr', true, 'Bangkok s''étend le long du fleuve Chao Phraya qui traverse le centre de la ville.'),
('geography', 3, 'Quel pays produit le plus de cacao au monde ?', 'La Côte d''Ivoire', ARRAY['Le Ghana', 'L''Indonésie', 'Le Brésil'], 'fr', true, 'La Côte d''Ivoire produit environ 40 % du cacao mondial, loin devant le Ghana.'),
('geography', 3, 'Quelle est la plus grande zone économique exclusive (ZEE) du monde ?', 'Celle de la France', ARRAY['Celle des États-Unis', 'Celle de l''Australie', 'Celle du Royaume-Uni'], 'fr', true, 'La France possède la plus grande ZEE grâce à ses territoires d''outre-mer, couvrant environ 11 millions de km².'),
('geography', 3, 'Quel est le pays le moins peuplé d''Afrique ?', 'Les Seychelles', ARRAY['São Tomé-et-Príncipe', 'Le Cap-Vert', 'Les Comores'], 'fr', true, 'Les Seychelles comptent environ 100 000 habitants, ce qui en fait le pays le moins peuplé d''Afrique.'),
('geography', 3, 'Quel pays possède la Grande Barrière de corail ?', 'L''Australie', ARRAY['L''Indonésie', 'Les Philippines', 'La Thaïlande'], 'fr', true, 'La Grande Barrière de corail s''étend sur 2 300 km le long de la côte nord-est de l''Australie.'),
('geography', 3, 'Quelle ville africaine est le siège de l''Union africaine ?', 'Addis-Abeba', ARRAY['Nairobi', 'Le Caire', 'Abuja'], 'fr', true, 'Addis-Abeba, capitale de l''Éthiopie, abrite le siège de l''Union africaine depuis sa fondation.'),
('geography', 3, 'Quel pays est le seul au monde à avoir le Coran inscrit sur son drapeau ?', 'L''Arabie saoudite', ARRAY['L''Iran', 'Le Pakistan', 'L''Afghanistan'], 'fr', true, 'Le drapeau saoudien porte la shahada (déclaration de foi) et un sabre sur fond vert.'),
('geography', 3, 'Quel fleuve d''Afrique forme les célèbres chutes Victoria ?', 'Le Zambèze', ARRAY['Le Congo', 'Le Nil', 'Le Niger'], 'fr', true, 'Les chutes Victoria se trouvent sur le Zambèze, à la frontière entre la Zambie et le Zimbabwe.'),
('geography', 3, 'Quelle est la plus grande île de France métropolitaine ?', 'La Corse', ARRAY['L''île d''Oléron', 'L''île de Ré', 'Belle-Île'], 'fr', true, 'La Corse est la plus grande île de France métropolitaine avec 8 680 km² de superficie.'),
('geography', 3, 'Quel détroit sépare le Maroc de l''Espagne ?', 'Le détroit de Gibraltar', ARRAY['Le détroit du Bosphore', 'Le détroit de Malacca', 'Le détroit de Magellan'], 'fr', true, 'Le détroit de Gibraltar ne fait que 14 km de large à son point le plus étroit.'),
('geography', 3, 'Quel pays d''Amérique du Sud est le seul à avoir l''anglais comme langue officielle ?', 'Le Guyana', ARRAY['Le Suriname', 'Le Belize', 'La Guyane française'], 'fr', true, 'Le Guyana est un ancien territoire britannique, le seul pays anglophone d''Amérique du Sud.'),
('geography', 3, 'Quelle est la capitale de l''Azerbaïdjan ?', 'Bakou', ARRAY['Erevan', 'Tbilissi', 'Téhéran'], 'fr', true, 'Bakou est la capitale de l''Azerbaïdjan, située sur la côte de la mer Caspienne.'),
('geography', 3, 'Quel pays possède le réseau de trains à grande vitesse le plus étendu ?', 'La Chine', ARRAY['Le Japon', 'La France', 'L''Espagne'], 'fr', true, 'Le réseau TGV chinois dépasse 42 000 km, le plus grand réseau à grande vitesse au monde.'),
('geography', 3, 'Quelle montagne est la plus haute d''Afrique ?', 'Le Kilimandjaro', ARRAY['Le mont Kenya', 'Le Ras Dashan', 'Le mont Cameroun'], 'fr', true, 'Le Kilimandjaro en Tanzanie culmine à 5 895 m, c''est un volcan dormant couvert de neige.'),
('geography', 3, 'Quel est le seul continent habité qui se trouve entièrement dans l''hémisphère sud ?', 'L''Australie/Océanie', ARRAY['L''Amérique du Sud', 'L''Afrique', 'L''Antarctique'], 'fr', true, 'L''Australie est le seul continent habité situé entièrement dans l''hémisphère sud.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 4, 'Quel pays africain est le seul dont la capitale est nommée d''après un président américain ?', 'Le Liberia (Monrovia)', ARRAY['Le Sierra Leone (Freetown)', 'Le Ghana (Accra)', 'Le Cameroun (Yaoundé)'], 'fr', true, 'Monrovia, capitale du Liberia, est nommée en l''honneur du président américain James Monroe.'),
('geography', 4, 'Quel est le seul endroit au monde où quatre pays se rencontrent en un point ?', 'Il n''existe aucun quadripoint reconnu internationalement', ARRAY['L''Afrique australe', 'L''Asie centrale', 'L''Europe de l''Est'], 'fr', true, 'Bien que le quadripoint de l''Afrique australe (Botswana, Namibie, Zambie, Zimbabwe) soit souvent cité, son existence exacte est contestée.'),
('geography', 4, 'Quelle est la seule mégapole qui s''étend sur deux continents ?', 'Istanbul', ARRAY['Le Caire', 'Moscou', 'Dubaï'], 'fr', true, 'Istanbul est la seule mégapole (plus de 15 millions d''habitants) à cheval sur l''Europe et l''Asie.'),
('geography', 4, 'Quel pays possède le plus grand nombre de voisins frontaliers ?', 'La Chine et la Russie (14 chacun)', ARRAY['Le Brésil (10)', 'L''Allemagne (9)', 'La France (8)'], 'fr', true, 'La Chine et la Russie partagent chacune des frontières terrestres avec 14 pays différents.'),
('geography', 4, 'Quel fleuve d''Asie centrale se jette dans la mer d''Aral, aujourd''hui quasi asséchée ?', 'L''Amou-Daria', ARRAY['Le Gange', 'L''Indus', 'L''Irtysh'], 'fr', true, 'L''Amou-Daria et le Syr-Daria alimentaient la mer d''Aral, mais les détournements d''eau l''ont presque asséchée.'),
('geography', 4, 'Quelle île du Pacifique est le pays le moins visité au monde ?', 'Tuvalu', ARRAY['Nauru', 'Les Palaos', 'Les Kiribati'], 'fr', true, 'Tuvalu reçoit moins de 2 000 touristes par an, en partie à cause de son isolement extrême.'),
('geography', 4, 'Quel est le nom de la ligne imaginaire qui sépare la faune asiatique de la faune australasienne ?', 'La ligne Wallace', ARRAY['La ligne de Démarcation', 'Le méridien de Greenwich', 'Le tropique du Cancer'], 'fr', true, 'La ligne Wallace sépare les zones biogéographiques asiatique et australasienne en Indonésie.'),
('geography', 4, 'Quel pays possède Socotra, une île à la biodiversité unique ?', 'Le Yémen', ARRAY['Oman', 'Djibouti', 'La Somalie'], 'fr', true, 'Socotra, au large du Yémen, possède une flore et une faune si uniques qu''on la surnomme les Galápagos de l''océan Indien.'),
('geography', 4, 'Quel est le seul pays au monde qui change de fuseau horaire de 45 minutes ?', 'Le Népal', ARRAY['L''Inde', 'L''Iran', 'L''Afghanistan'], 'fr', true, 'Le Népal utilise UTC+5:45, le seul décalage de 45 minutes au monde.'),
('geography', 4, 'Quelle ville est la plus peuplée de l''hémisphère sud ?', 'São Paulo', ARRAY['Jakarta', 'Buenos Aires', 'Sydney'], 'fr', true, 'São Paulo au Brésil compte plus de 12 millions d''habitants, la plus grande ville de l''hémisphère sud.'),
('geography', 4, 'Quel pays d''Asie centrale est le plus grand pays enclavé du monde ?', 'Le Kazakhstan', ARRAY['La Mongolie', 'L''Éthiopie', 'Le Tchad'], 'fr', true, 'Le Kazakhstan est le plus grand pays sans accès à la mer avec 2,72 millions de km².'),
('geography', 4, 'Quel site UNESCO en Turquie est connu pour ses cheminées de fée ?', 'La Cappadoce', ARRAY['Éphèse', 'Pamukkale', 'Troie'], 'fr', true, 'La Cappadoce en Turquie est célèbre pour ses formations rocheuses en forme de cheminées de fée et ses habitations troglodytes.'),
('geography', 4, 'Quel est le pays le plus boisé d''Europe (pourcentage de forêt) ?', 'La Finlande', ARRAY['La Suède', 'La Russie européenne', 'La Slovénie'], 'fr', true, 'Environ 73 % du territoire finlandais est recouvert de forêts, le plus haut pourcentage en Europe.'),
('geography', 4, 'Quelle capitale du monde se trouve le plus près de l''équateur ?', 'Quito', ARRAY['Singapour', 'Nairobi', 'Bogota'], 'fr', true, 'Quito, capitale de l''Équateur, se trouve à seulement 22 km au sud de l''équateur.'),
('geography', 4, 'Quel petit pays européen a le PIB par habitant le plus élevé au monde ?', 'Le Luxembourg', ARRAY['Monaco', 'Le Liechtenstein', 'La Suisse'], 'fr', true, 'Le Luxembourg possède le PIB par habitant le plus élevé au monde grâce à son secteur financier.'),
('geography', 4, 'Quelle mer est considérée comme le plus grand lac du monde ?', 'La mer Caspienne', ARRAY['La mer Morte', 'La mer d''Aral', 'Le lac Baïkal'], 'fr', true, 'La mer Caspienne est techniquement un lac endoréique (sans sortie vers l''océan) couvrant 371 000 km².'),
('geography', 4, 'Quel pays possède l''archipel de Svalbard dans l''Arctique ?', 'La Norvège', ARRAY['Le Danemark', 'La Russie', 'Le Canada'], 'fr', true, 'Le Svalbard est un archipel norvégien dans l''Arctique, où se trouve Longyearbyen, la ville la plus septentrionale du monde.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 5, 'Quel est le nom du point triple géologique où se rencontrent les plaques africaine, arabe et somalienne ?', 'Le triangle d''Afar', ARRAY['Le rift du Baïkal', 'La dorsale médio-atlantique', 'La faille de San Andreas'], 'fr', true, 'Le triangle d''Afar en Éthiopie/Djibouti/Érythrée est un point triple tectonique où trois plaques divergent.'),
('geography', 5, 'Quel pays possède le plus d''enclaves et d''exclaves au monde ?', 'L''Inde et le Bangladesh', ARRAY['L''Espagne et le Maroc', 'L''Ouzbékistan et le Kirghizistan', 'La Belgique et les Pays-Bas'], 'fr', true, 'Jusqu''en 2015, l''Inde et le Bangladesh partageaient plus de 160 enclaves et exclaves avant un échange de territoires.'),
('geography', 5, 'Quel est le nom du courant thermohalin global qui régule le climat mondial ?', 'La circulation thermohaline (le tapis roulant océanique)', ARRAY['Le Gulf Stream uniquement', 'Le courant circumpolaire', 'La dérive nord-atlantique'], 'fr', true, 'La circulation thermohaline est un système de courants océaniques profonds qui redistribue la chaleur autour du globe.'),
('geography', 5, 'Quel micro-État européen a la particularité d''être gouverné par deux co-princes ?', 'Andorre', ARRAY['Monaco', 'Saint-Marin', 'Le Liechtenstein'], 'fr', true, 'Andorre est gouvernée par deux co-princes : l''évêque d''Urgell et le président de la République française.'),
('geography', 5, 'Quel est le nom du phénomène géographique où une rivière coule dans deux directions différentes ?', 'Un cours d''eau bifurqué', ARRAY['Un méandre', 'Un delta inversé', 'Un confluent'], 'fr', true, 'Le canal du Casiquiare au Venezuela relie l''Orénoque à l''Amazone, un rare exemple de bifurcation fluviale naturelle.'),
('geography', 5, 'Quelle ville détient le record de la température la plus élevée jamais enregistrée sur Terre ?', 'Furnace Creek (Vallée de la Mort)', ARRAY['Aziziya (Libye)', 'Dallol (Éthiopie)', 'Bandar-e Mahshahr (Iran)'], 'fr', true, 'Furnace Creek dans la Vallée de la Mort a enregistré 56,7°C le 10 juillet 1913.'),
('geography', 5, 'Quel est le concept géopolitique de la ligne Radcliffe ?', 'La frontière tracée lors de la partition de l''Inde et du Pakistan en 1947', ARRAY['La frontière entre les deux Corées', 'La ligne de démarcation au Vietnam', 'La frontière entre Israël et la Palestine'], 'fr', true, 'La ligne Radcliffe, tracée par Sir Cyril Radcliffe, a divisé l''Inde britannique en Inde et Pakistan.'),
('geography', 5, 'Quel phénomène géologique explique que l''Islande s''agrandit chaque année ?', 'La divergence des plaques nord-américaine et eurasienne', ARRAY['L''érosion glaciaire', 'L''accumulation de sédiments', 'Le soulèvement post-glaciaire'], 'fr', true, 'L''Islande se situe sur la dorsale médio-atlantique où deux plaques tectoniques s''écartent d''environ 2,5 cm par an.'),
('geography', 5, 'Quelle est la seule ville au monde inscrite intégralement au patrimoine mondial de l''UNESCO ?', 'Luxembourg (vieux quartiers et fortifications)', ARRAY['Venise', 'Dubrovnik', 'Prague'], 'fr', true, 'Bien que de nombreuses villes aient des centres historiques classés, les vieux quartiers de Luxembourg sont inscrits pour leur ensemble fortifié exceptionnel.'),
('geography', 5, 'Quel pays détient le record de la plus grande différence d''altitude entre son point le plus bas et le plus haut ?', 'La Chine', ARRAY['Le Népal', 'Le Pérou', 'L''Argentine'], 'fr', true, 'La Chine va de la dépression de Turpan (-154 m) au mont Everest (8 849 m), soit près de 9 000 m de dénivelé.'),
('geography', 5, 'Quel est le nom de la théorie selon laquelle les villes suivent une loi de distribution rang-taille ?', 'La loi de Zipf', ARRAY['La loi de Pareto', 'La loi de Weber', 'La théorie des lieux centraux'], 'fr', true, 'La loi de Zipf prédit que la deuxième plus grande ville d''un pays sera environ la moitié de la première, la troisième un tiers, etc.');
