('geography', 2, 'Which country has the longest fjord in the world?', 'Norway', ARRAY['Chile', 'Canada', 'New Zealand'], 'en', true, 'Sognefjord in Norway is 204 km long and 1,308 m deep, the world''s longest fjord.'),
('geography', 2, 'What is the most populous city in South America?', 'Sao Paulo', ARRAY['Buenos Aires', 'Rio de Janeiro', 'Bogota'], 'en', true, 'Sao Paulo, Brazil is the largest city in South America with over 12 million inhabitants (22 million in the metro area).'),
('geography', 2, 'Which country lies entirely above 1,000 meters in altitude?', 'Lesotho', ARRAY['Switzerland', 'Nepal', 'Bhutan'], 'en', true, 'Lesotho is the only country in the world where all of its territory is above 1,000 meters elevation.'),
('geography', 2, 'What strait connects the Mediterranean Sea to the Black Sea?', 'The Dardanelles and Bosphorus', ARRAY['The Strait of Gibraltar', 'The Suez Canal', 'The Strait of Messina'], 'en', true, 'The Mediterranean connects to the Black Sea via the Dardanelles, the Sea of Marmara, and the Bosphorus.'),
('geography', 2, 'What is the capital of Kenya?', 'Nairobi', ARRAY['Mombasa', 'Dar es Salaam', 'Kampala'], 'en', true, 'Nairobi is the capital of Kenya and a major economic hub of East Africa.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 3, 'What country has Ulaanbaatar as its capital?', 'Mongolia', ARRAY['Kazakhstan', 'Kyrgyzstan', 'Turkmenistan'], 'en', true, 'Ulaanbaatar is the capital of Mongolia, home to nearly half the country''s population.'),
('geography', 3, 'Which island is shared by Indonesia, Malaysia, and Brunei?', 'Borneo', ARRAY['Sumatra', 'Java', 'Sulawesi'], 'en', true, 'Borneo is the third-largest island in the world, divided among three countries.'),
('geography', 3, 'Which country has the largest lithium reserves in the world?', 'Bolivia', ARRAY['Australia', 'Chile', 'Argentina'], 'en', true, 'The Salar de Uyuni in Bolivia contains the world''s largest known lithium reserves.'),
('geography', 3, 'What is the northernmost city in the world with over 100,000 inhabitants?', 'Murmansk', ARRAY['Tromso', 'Reykjavik', 'Anchorage'], 'en', true, 'Murmansk, Russia, is the largest city above the Arctic Circle with about 280,000 people.'),
('geography', 3, 'Which country is the world''s largest diamond exporter?', 'Russia', ARRAY['Botswana', 'South Africa', 'Angola'], 'en', true, 'Russia is the world''s top producer of rough diamonds, primarily from Yakutia.'),
('geography', 3, 'What is the capital of Bhutan?', 'Thimphu', ARRAY['Kathmandu', 'Dhaka', 'Colombo'], 'en', true, 'Thimphu is the capital of Bhutan, a small Himalayan kingdom that measures Gross National Happiness.'),
('geography', 3, 'Which European river flows through the most capital cities?', 'The Danube', ARRAY['The Rhine', 'The Seine', 'The Thames'], 'en', true, 'The Danube flows through four capitals: Vienna, Bratislava, Budapest, and Belgrade.'),
('geography', 3, 'Which Icelandic volcanic island was born from an underwater eruption in 1963?', 'Surtsey', ARRAY['Heimaey', 'Grimsey', 'Flatey'], 'en', true, 'Surtsey emerged from underwater eruptions between 1963 and 1967 and became a UNESCO site in 2008.'),
('geography', 3, 'Which country has the most national parks in the world?', 'Australia', ARRAY['United States', 'Brazil', 'China'], 'en', true, 'Australia has over 500 national parks spread across the continent.'),
('geography', 3, 'What is the most remote point from any ocean on Earth?', 'The continental pole of inaccessibility in Central Asia', ARRAY['The center of the Sahara', 'Tibet', 'Central Australia'], 'en', true, 'The point farthest from any ocean is in northwestern China, about 2,645 km from the nearest coast.'),
('geography', 3, 'Which African city is nicknamed the White City?', 'Algiers', ARRAY['Casablanca', 'Tunis', 'Cairo'], 'en', true, 'Algiers is nicknamed the White City due to its white-washed buildings along the Mediterranean coast.'),
('geography', 3, 'Which South American country has two official capitals?', 'Bolivia', ARRAY['Peru', 'Ecuador', 'Paraguay'], 'en', true, 'Bolivia has Sucre as its constitutional capital and La Paz as the seat of government.'),
('geography', 3, 'What is the largest island of Japan?', 'Honshu', ARRAY['Hokkaido', 'Kyushu', 'Shikoku'], 'en', true, 'Honshu is Japan''s largest island at 227,960 km², home to Tokyo, Osaka, and Kyoto.'),
('geography', 3, 'Which country has the highest population density in the world?', 'Monaco', ARRAY['Singapore', 'Vatican City', 'Malta'], 'en', true, 'Monaco has a density of about 26,000 people per km², the highest in the world.'),
('geography', 3, 'Which UNESCO site is home to the famous Moai statues?', 'Easter Island (Rapa Nui)', ARRAY['Galapagos', 'Hawaii', 'Tonga'], 'en', true, 'Easter Island, a Chilean territory in the Pacific, is famous for its 887 monumental Moai statues.'),
('geography', 3, 'Which European country has the most lakes?', 'Finland', ARRAY['Sweden', 'Norway', 'Russia'], 'en', true, 'Finland has about 188,000 lakes, earning it the nickname Land of a Thousand Lakes.'),
('geography', 3, 'What is the highest capital city in the world?', 'La Paz (Bolivia)', ARRAY['Quito (Ecuador)', 'Bogota (Colombia)', 'Addis Ababa (Ethiopia)'], 'en', true, 'La Paz sits at about 3,640 m altitude, making it the highest de facto capital in the world.'),
('geography', 3, 'Which is the only country with a non-rectangular flag?', 'Nepal', ARRAY['Switzerland', 'Vatican City', 'Bhutan'], 'en', true, 'Nepal''s flag consists of two stacked triangles, unique among all national flags.'),
('geography', 3, 'Which country has the world''s largest boreal forest (taiga)?', 'Russia', ARRAY['Canada', 'Finland', 'Sweden'], 'en', true, 'The Russian taiga is the world''s largest forest, covering about 12 million km².'),
('geography', 3, 'What Southeast Asian capital sits on the Chao Phraya River?', 'Bangkok', ARRAY['Hanoi', 'Phnom Penh', 'Jakarta'], 'en', true, 'Bangkok stretches along the Chao Phraya River, which flows through the heart of the city.'),
('geography', 3, 'Which country produces the most cocoa in the world?', 'Ivory Coast (Cote d''Ivoire)', ARRAY['Ghana', 'Indonesia', 'Brazil'], 'en', true, 'Ivory Coast produces about 40% of the world''s cocoa, far ahead of Ghana.'),
('geography', 3, 'Which country has the largest exclusive economic zone (EEZ)?', 'France', ARRAY['United States', 'Australia', 'United Kingdom'], 'en', true, 'France has the largest EEZ thanks to its overseas territories, covering about 11 million km².'),
('geography', 3, 'What is the least populated country in Africa?', 'Seychelles', ARRAY['Sao Tome and Principe', 'Cape Verde', 'Comoros'], 'en', true, 'Seychelles has about 100,000 inhabitants, making it the least populated African country.'),
('geography', 3, 'Which country owns the Great Barrier Reef?', 'Australia', ARRAY['Indonesia', 'Philippines', 'Thailand'], 'en', true, 'The Great Barrier Reef stretches 2,300 km along the northeast coast of Australia.'),
('geography', 3, 'Which African city hosts the African Union headquarters?', 'Addis Ababa', ARRAY['Nairobi', 'Cairo', 'Abuja'], 'en', true, 'Addis Ababa, the Ethiopian capital, has housed the African Union since its founding.'),
('geography', 3, 'Which African river forms the famous Victoria Falls?', 'The Zambezi', ARRAY['The Congo', 'The Nile', 'The Niger'], 'en', true, 'Victoria Falls is on the Zambezi River at the border of Zambia and Zimbabwe.'),
('geography', 3, 'Which strait separates Morocco from Spain?', 'The Strait of Gibraltar', ARRAY['The Bosphorus', 'The Strait of Malacca', 'The Strait of Magellan'], 'en', true, 'The Strait of Gibraltar is just 14 km wide at its narrowest point.'),
('geography', 3, 'Which South American country is the only one with English as its official language?', 'Guyana', ARRAY['Suriname', 'Belize', 'French Guiana'], 'en', true, 'Guyana is a former British territory and the only English-speaking country in South America.'),
('geography', 3, 'What is the capital of Azerbaijan?', 'Baku', ARRAY['Yerevan', 'Tbilisi', 'Tehran'], 'en', true, 'Baku is the capital of Azerbaijan, located on the coast of the Caspian Sea.'),
('geography', 3, 'Which country has the most extensive high-speed rail network?', 'China', ARRAY['Japan', 'France', 'Spain'], 'en', true, 'China''s high-speed rail network exceeds 42,000 km, the world''s largest.'),
('geography', 3, 'What is the highest mountain in Africa?', 'Mount Kilimanjaro', ARRAY['Mount Kenya', 'Ras Dashen', 'Mount Cameroon'], 'en', true, 'Kilimanjaro in Tanzania stands at 5,895 m, a dormant volcano with a snow-capped peak.'),
('geography', 3, 'Which is the only inhabited continent entirely in the Southern Hemisphere?', 'Australia/Oceania', ARRAY['South America', 'Africa', 'Antarctica'], 'en', true, 'Australia is the only inhabited continent located entirely in the Southern Hemisphere.'),
('geography', 3, 'Which is the only country whose flag features a building (a temple)?', 'Cambodia', ARRAY['Afghanistan', 'Mozambique', 'Spain'], 'en', true, 'Cambodia''s flag features the temple of Angkor Wat, the famous UNESCO World Heritage Site.'),
('geography', 3, 'What is the largest island in the Mediterranean Sea?', 'Sicily', ARRAY['Sardinia', 'Corsica', 'Crete'], 'en', true, 'Sicily, part of Italy, is the largest island in the Mediterranean at 25,711 km².'),
('geography', 3, 'Which country has the world''s largest proven oil reserves?', 'Venezuela', ARRAY['Saudi Arabia', 'Canada', 'Iran'], 'en', true, 'Venezuela holds the world''s largest proven oil reserves at about 300 billion barrels.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 4, 'Which African country''s capital is named after a US president?', 'Liberia (Monrovia)', ARRAY['Sierra Leone (Freetown)', 'Ghana (Accra)', 'Cameroon (Yaounde)'], 'en', true, 'Monrovia, capital of Liberia, is named after US President James Monroe.'),
('geography', 4, 'Does a recognized quadripoint (where four countries meet) exist on Earth?', 'No internationally recognized quadripoint exists', ARRAY['Yes, in Southern Africa', 'Yes, in Central Asia', 'Yes, in Eastern Europe'], 'en', true, 'The supposed quadripoint where Botswana, Namibia, Zambia, and Zimbabwe meet is disputed and likely not exact.'),
('geography', 4, 'What is the only megacity that spans two continents?', 'Istanbul', ARRAY['Cairo', 'Moscow', 'Dubai'], 'en', true, 'Istanbul is the only megacity (over 15 million people) that straddles both Europe and Asia.'),
('geography', 4, 'Which country shares borders with the most other nations?', 'China and Russia (14 each)', ARRAY['Brazil (10)', 'Germany (9)', 'France (8)'], 'en', true, 'China and Russia each share land borders with 14 different countries.'),
('geography', 4, 'Which Central Asian river feeds the now nearly-dry Aral Sea?', 'The Amu Darya', ARRAY['The Ganges', 'The Indus', 'The Irtysh'], 'en', true, 'The Amu Darya and Syr Darya once fed the Aral Sea, but irrigation diversions have almost dried it up.'),
('geography', 4, 'Which Pacific island nation is the least visited country in the world?', 'Tuvalu', ARRAY['Nauru', 'Palau', 'Kiribati'], 'en', true, 'Tuvalu receives fewer than 2,000 tourists per year due to its extreme isolation.'),
('geography', 4, 'What is the Wallace Line?', 'A biogeographical boundary between Asian and Australasian fauna', ARRAY['A political border', 'The Prime Meridian', 'The Tropic of Cancer'], 'en', true, 'The Wallace Line separates the Asian and Australasian biogeographic zones across Indonesia.'),
('geography', 4, 'Which country owns Socotra, an island with unique biodiversity?', 'Yemen', ARRAY['Oman', 'Djibouti', 'Somalia'], 'en', true, 'Socotra, off Yemen''s coast, has such unique flora and fauna it''s called the Galapagos of the Indian Ocean.'),
('geography', 4, 'Which is the only country that uses a 45-minute time zone offset?', 'Nepal', ARRAY['India', 'Iran', 'Afghanistan'], 'en', true, 'Nepal uses UTC+5:45, the only 45-minute offset in the world.'),
('geography', 4, 'What is the most populous city in the Southern Hemisphere?', 'Sao Paulo', ARRAY['Jakarta', 'Buenos Aires', 'Sydney'], 'en', true, 'Sao Paulo, Brazil has over 12 million inhabitants, the largest city south of the equator.'),
('geography', 4, 'What is the world''s largest landlocked country?', 'Kazakhstan', ARRAY['Mongolia', 'Ethiopia', 'Chad'], 'en', true, 'Kazakhstan is the world''s largest landlocked country at 2.72 million km².'),
('geography', 4, 'Which UNESCO site in Turkey is known for its fairy chimneys?', 'Cappadocia', ARRAY['Ephesus', 'Pamukkale', 'Troy'], 'en', true, 'Cappadocia in Turkey is famous for its fairy chimney rock formations and cave dwellings.'),
('geography', 4, 'Which European country has the highest percentage of forest cover?', 'Finland', ARRAY['Sweden', 'European Russia', 'Slovenia'], 'en', true, 'About 73% of Finland''s territory is covered by forest, the highest percentage in Europe.'),
('geography', 4, 'Which world capital is closest to the equator?', 'Quito', ARRAY['Singapore', 'Nairobi', 'Bogota'], 'en', true, 'Quito, the capital of Ecuador, lies just 22 km south of the equator.'),
('geography', 4, 'Which small European country has the highest GDP per capita in the world?', 'Luxembourg', ARRAY['Monaco', 'Liechtenstein', 'Switzerland'], 'en', true, 'Luxembourg has the world''s highest GDP per capita, driven by its financial sector.'),
('geography', 4, 'Which sea is actually considered the world''s largest lake?', 'The Caspian Sea', ARRAY['The Dead Sea', 'The Aral Sea', 'Lake Baikal'], 'en', true, 'The Caspian Sea is technically an endorheic lake (no outlet to the ocean) covering 371,000 km².'),
('geography', 4, 'Which country owns the Svalbard archipelago in the Arctic?', 'Norway', ARRAY['Denmark', 'Russia', 'Canada'], 'en', true, 'Svalbard is a Norwegian Arctic archipelago home to Longyearbyen, the world''s northernmost town.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('geography', 5, 'What is the Afar Triple Junction?', 'A geological point where the African, Arabian, and Somali plates meet', ARRAY['The Baikal Rift', 'The Mid-Atlantic Ridge', 'The San Andreas Fault'], 'en', true, 'The Afar Triangle in Ethiopia/Djibouti/Eritrea is a tectonic triple point where three plates are diverging.'),
('geography', 5, 'Which pair of countries historically shared the most enclaves and exclaves?', 'India and Bangladesh', ARRAY['Spain and Morocco', 'Uzbekistan and Kyrgyzstan', 'Belgium and the Netherlands'], 'en', true, 'Until 2015, India and Bangladesh shared over 160 enclaves before a land-swap agreement resolved most of them.'),
('geography', 5, 'What is the global thermohaline circulation?', 'A system of deep ocean currents that redistributes heat worldwide', ARRAY['The Gulf Stream only', 'The circumpolar current', 'The North Atlantic Drift'], 'en', true, 'The thermohaline circulation (ocean conveyor belt) is driven by differences in water temperature and salinity.'),
('geography', 5, 'Which European microstate is governed by two co-princes?', 'Andorra', ARRAY['Monaco', 'San Marino', 'Liechtenstein'], 'en', true, 'Andorra is governed by two co-princes: the Bishop of Urgell and the President of France.'),
('geography', 5, 'What is a river bifurcation?', 'When a river splits and flows in two different directions to different basins', ARRAY['A meandering river', 'An inverted delta', 'A confluence'], 'en', true, 'The Casiquiare canal in Venezuela connects the Orinoco to the Amazon, a rare natural river bifurcation.'),
('geography', 5, 'Which location holds the record for the highest temperature ever recorded on Earth?', 'Furnace Creek (Death Valley)', ARRAY['Aziziya (Libya)', 'Dallol (Ethiopia)', 'Bandar-e Mahshahr (Iran)'], 'en', true, 'Furnace Creek in Death Valley recorded 56.7C (134F) on July 10, 1913.'),
('geography', 5, 'What was the Radcliffe Line?', 'The border drawn during the 1947 partition of India and Pakistan', ARRAY['The border between the two Koreas', 'The demarcation line in Vietnam', 'The border between Israel and Palestine'], 'en', true, 'The Radcliffe Line, drawn by Sir Cyril Radcliffe, divided British India into India and Pakistan.'),
('geography', 5, 'What geological phenomenon causes Iceland to grow each year?', 'The divergence of the North American and Eurasian plates', ARRAY['Glacial erosion', 'Sediment accumulation', 'Post-glacial rebound'], 'en', true, 'Iceland sits on the Mid-Atlantic Ridge where two tectonic plates separate by about 2.5 cm per year.'),
('geography', 5, 'Which country holds the record for the greatest altitude difference between its lowest and highest points?', 'China', ARRAY['Nepal', 'Peru', 'Argentina'], 'en', true, 'China ranges from the Turpan Depression (-154 m) to Mount Everest (8,849 m), nearly 9,000 m of difference.'),
('geography', 5, 'What is the rank-size rule (Zipf''s Law) in urban geography?', 'A city''s population is inversely proportional to its rank', ARRAY['The Pareto principle', 'Weber''s theory', 'Central place theory'], 'en', true, 'Zipf''s Law predicts that the second-largest city will be about half the size of the first, the third about a third, etc.'),
('geography', 5, 'What is the significance of the Isthmus of Panama in biogeography?', 'Its formation 3 million years ago triggered the Great American Biotic Interchange', ARRAY['It blocked the Atlantic current', 'It created the Pacific Ring of Fire', 'It separated North American species permanently'], 'en', true, 'The closing of the Isthmus of Panama allowed species migration between North and South America, transforming both continents'' fauna.');
